import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { FRAME_MS, frameFile, imageSource, lookKey } from './creatures'
import {
  buildWorkers, clock, DETAILS, drawScene, encode, isActive, isVisible, LABEL, msysToWin, parseEvents, sceneRows, sceneSvg, SPRITE_COLS, SPRITE_ROWS,
  type Meta, type Run, type State, type Worker,
} from './scene'

const PANE = 'cw-crew'
const DAY = 86_400_000
const slots = atom({ plugin: 'cw-crew', key: 'slots' } as const, 0)
const selected = atom({ plugin: 'cw-crew', key: 'selected' } as const, '')
const NOTES = 4, STEPS = 10, REPORT_CHARS = 2400
type Tracked = Run & { size: number; final: boolean }

// Module state: a reload starts it over and the next poll rebuilds it from the run files.
let dir = ''
let session = ''
let metas = new Map<string, Meta | null>()
let runs = new Map<string, Tracked>()
let workers: Worker[] = []
let mounted: { cols: number; rows: number; maxRows: number; images: boolean; keys: Set<string> } | undefined
// Sprites are Images until the terminal shows it draws their alt instead (no image protocol,
// tmux): a blit of a mounted Image is then denied, and the pane falls back to half-blocks.
let images = true
let refused = 0
let shown = new Map<string, string>()
let seen = new Map<string, State>()
let status: string | undefined
let opened = false
let polling = false
let lastKick = 0
// Surfaces with no Raster (desktop, editor, mobile) get the scene as an Svg, redrawn by poll() while shown.
let svgAt = 0
let svgKick = 0
// PNG frames as base64, read once each; a session sees a few dozen of the 650.
const pngs = new Map<string, string>()
// Detail view: the open worker's live notes (its assistant text) and final report, refreshed by poll().
let selKey = ''
let detail: { key: string; size: number; notes: string[]; report?: string } = { key: '', size: -1, notes: [] }

function readText($: EngineInterface, name: string) {
  return $.fs.read(`${dir}/${name}`).catch(() => undefined)
}

async function poll($: EngineInterface) {
  if (polling) return
  polling = true
  try {
    const sid = await $.session.id()
    if (sid !== session) {
      session = sid
      metas = new Map(); runs = new Map(); seen = new Map()
    }
    const now = await $.clock.now()
    const entries = await $.fs.list(dir).catch(() => [])
    const byName = new Map(entries.map(en => [en.name, en]))

    for (const en of entries) {
      if (!en.name.endsWith('.meta')) continue
      const id = en.name.slice(0, -'.meta'.length)
      if (!metas.has(id)) {
        if (now - en.mtimeMs > DAY) { metas.set(id, null); continue }
        const text = await readText($, en.name)
        let meta: Meta | undefined
        try { meta = text ? (JSON.parse(text) as Meta) : undefined } catch { meta = undefined }
        if (!meta) continue
        // A resumed/restarted lead gets a new session id: keep showing the workers still running from before.
        const live = !byName.has(`${id}.done`) && now / 1000 - meta.start < (meta.tmo ?? 3600) + 2400   // + cw's acceptance run
        metas.set(id, meta.session === session || live ? meta : null)
      }
      const meta = metas.get(id)
      if (!meta) continue
      const run = runs.get(id) ?? { id, meta, events: [], size: -1, final: false }
      if (run.final) {
        // The lead closed the request without a resume (cwopen -x): lower the hand.
        if (run.question !== undefined && !byName.has(`${id}.ask`)) runs = new Map(runs).set(id, { ...run, question: undefined })
        continue
      }
      const ev = byName.get(`${id}.events`)
      const done = byName.get(`${id}.done`)
      let next: Tracked = run
      // The events file is complete once .done exists, so read it one last time then.
      if (ev && (ev.size !== run.size || done)) {
        next = { ...next, events: parseEvents((await readText($, ev.name)) ?? ''), size: ev.size }
      }
      if (done) {
        const rc = Number.parseInt((await readText($, done.name)) ?? '', 10)
        const question = byName.has(`${id}.ask`) ? (await readText($, `${id}.ask`))?.trim() : undefined
        next = { ...next, rc: Number.isNaN(rc) ? 1 : rc, doneAt: done.mtimeMs, question, final: true }
      }
      if (next !== run || !runs.has(id)) runs = new Map(runs).set(id, next)
    }

    const all = buildWorkers([...runs.values()], now)
    announce($, all)
    const visible = all.filter(w => isVisible(w, now))
    const grew = visible.length !== workers.length
    workers = visible
    if (grew) await update($, slots, () => visible.length)

    const active = all.filter(isActive).length
    const asking = all.filter(w => w.state === 'ask').length
    const text = active ? `⚒ ${active} working${asking ? ` · ${asking} asking` : ''}`
      : asking ? `? ${asking} waiting for an answer` : undefined
    if (text !== status) { status = text; $.ui.status(text) }

    if (active && !opened) {
      opened = true
      const res = await $.ui.open(paneArgs())
      if (!res.isPlaced) $.ui.toast('cw-crew: workers running, open the pane with /crew')
    }
    // A pane hidden behind a tab drops its Raster; ask for a redraw now and then so the animation resumes.
    if (!mounted && opened && now - lastKick > 2000) { lastKick = now; $.ui.invalidate('ui.render') }
    // ponytail: whole-Svg redraw per poll, no per-frame blit there; fine for a handful of workers.
    else if (!selKey && now - svgAt < 5000 && now - svgKick >= (active ? 400 : 2000)) { svgKick = now; $.ui.invalidate('ui.render') }
    if (selKey) await refreshDetail($, all, byName)
  } finally {
    polling = false
  }
}

// The open worker's newest run: its stream (.jsonl) holds the notes, its result (.json) the report.
async function refreshDetail($: EngineInterface, all: Worker[], byName: Map<string, { size: number }>) {
  const w = all.find(x => x.key === selKey)
  const id = w?.runIds.at(-1)
  if (!w || !id) return
  const size = byName.get(`${id}.jsonl`)?.size ?? 0
  if (detail.key === w.key && detail.size === size && (w.end === undefined || detail.report !== undefined)) return
  const notes: string[] = []
  for (const line of ((await readText($, `${id}.jsonl`)) ?? '').split('\n')) {
    if (!line.includes('"type":"assistant"')) continue
    try {
      const m = JSON.parse(line) as { message?: { content?: { type: string; text?: string }[] } }
      for (const c of m.message?.content ?? []) if (c.type === 'text' && c.text?.trim()) notes.push(c.text.trim())
    } catch { /* a line still being written */ }
  }
  let report: string | undefined
  if (w.end !== undefined) {
    try { report = ((JSON.parse((await readText($, `${id}.json`)) ?? '{}') as { result?: string }).result ?? '').trim() } catch { report = '' }
  }
  detail = { key: w.key, size, notes: notes.slice(-NOTES), report }
  $.ui.invalidate('ui.render')
}

function openDetail($: EngineInterface, key: string) {
  selKey = key
  detail = { key: '', size: -1, notes: [] }
  mounted = undefined
  void update($, selected, () => key)
}

// Ask for the rows the scene needs (room for two workers once any run), not the default third of the screen.
const paneArgs = () => ({ id: PANE, title: 'Crew', rows: sceneRows(workers.length && Math.max(2, workers.length), 60), columns: 60 })

function announce($: EngineInterface, all: Worker[]) {
  // One state per key (the last run wins): two entries with one key would flip-flop and toast every poll.
  for (const w of new Map(all.map(w => [w.key, w])).values()) {
    const before = seen.get(w.key)
    seen.set(w.key, w.state)
    if (before === w.state || (before === undefined && w.end !== undefined)) continue
    if (w.state === 'ask') $.ui.toast(`? ${w.name} asks: ${w.question ?? ''}`, { timeoutMs: 8000 })
    else if (w.state === 'blocked') $.ui.toast(`! ${w.name} blocked: ${w.arg}`)
    else if (w.state === 'done') $.ui.toast(`✓ ${w.name} (${w.role}) done`)
    else if (w.state === 'failed') $.ui.toast(`✗ ${w.name} (${w.role}) failed`)
  }
}

async function paint($: EngineInterface) {
  const at = mounted
  const root = $.plugin.root
  if (!at || sceneRows(workers.length, at.cols, at.maxRows) !== at.rows) return
  const { words, spots } = drawScene(workers, at.cols, await $.clock.now(), at.maxRows, at.images)
  const res = await $.ui.blit({ requestId: PANE, key: 'crew', cells: encode(words) })
  if (res.deny) { mounted = undefined; return }
  // The cells went in, so the pane is mounted: an Image refused now is one drawing its alt.
  for (const s of spots) {
    const key = lookKey(s.look)
    if (!at.keys.has(s.key) || shown.get(s.key) === key) continue
    const img = await $.ui.blit({ requestId: PANE, key: s.key, source: imageSource(s.look, root) })
    if (img.deny) {
      if (/alt|placeholder|unsupported/i.test(img.deny) || ++refused >= 6) {
        images = false
        mounted = undefined
        $.ui.log(`cw-crew: no images here (${img.deny}); half-block sprites`)
        $.ui.invalidate('ui.render')
      }
      return
    }
    refused = 0
    shown.set(s.key, key)
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    session = await $.session.id()
    const home = (await $.env.get('HOME')) || (await $.env.get('USERPROFILE')) || ''
    dir = msysToWin((await $.env.get('CW_LOG_DIR')) || `${home}/.claude/cw-runs`).replace(/\\/g, '/')
    await $.command.register({ name: 'crew', description: 'Open the cw worker pane (Haiku scouts / Sonnet coders)' })
    $.clock.every(400, () => void poll($).catch(err => $.ui.log(`cw-crew poll: ${String(err)}`)))
    $.clock.every(FRAME_MS, () => void paint($).catch(() => { mounted = undefined }))
    return next(e)
  })

  // The engine docks a pane on the right only in the fullscreen layout from 110 columns; else it sits above the prompt.
  on('command.run', { command: 'crew' }, async ($, e) => {
    opened = true
    // A reload with the pane open can refuse the first blits before the pane mounts; /crew retries PNG sprites.
    images = true
    refused = 0
    mounted = undefined
    await $.ui.open(paneArgs())
    const { isFullscreen, columns } = e.presentation
    // The layout hints are the terminal's; the desktop places the pane itself.
    const where = (await $.env.get('CLAUDE_CODE_ENTRYPOINT')) === 'claude-desktop' ? ''
      : !isFullscreen
      ? ' It sits above the prompt: the right-side pane needs the fullscreen layout (CLAUDE_CODE_NO_FLICKER=1, outside tmux).'
      : columns < 110 ? ` It sits above the prompt: the right-side pane needs a terminal of at least 110 columns (now ${columns}).` : ''
    return { text: `Crew pane opened.${where}` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    await read($, slots)
    const sel = await read($, selected)
    const open = sel ? workers.find(w => w.key === sel) : undefined
    if (open) {
      mounted = undefined   // paint() must not blit the scene over the detail view
      const { Box, Text, Button } = $.ui.resolve(e)
      const now = await $.clock.now()
      const steps = (open.runIds.flatMap(id => runs.get(id)?.events ?? [])).filter(ev => ev.tool).slice(-STEPS)
      const ago = (t: number) => clock(Math.max(0, now - t))
      return (
        <Box flexDirection="column" paddingX={1}>
          <Box flexDirection="row" gap={1}>
            <Button key="back" hotkey="b" onPress={() => { selKey = ''; mounted = undefined; void update($, selected, () => '') }}>‹ back</Button>
            <Text bold>{open.name}</Text>
            <Text dimColor>{open.model} · {LABEL[open.state]} · {clock((open.end ?? now) - open.start)} · {open.turns} turns</Text>
          </Box>
          {open.state === 'ask' && open.question && <Text color="warning" wrap="wrap">? {open.question}</Text>}
          <Text bold>Task</Text>
          <Text dimColor wrap="wrap">{open.task.slice(0, 600)}</Text>
          <Text bold>Latest notes</Text>
          {detail.key !== open.key ? <Text dimColor>reading…</Text>
            : detail.notes.length === 0 ? <Text dimColor>no notes yet</Text>
            : detail.notes.map(n => <Text wrap="wrap">· {n.slice(0, 400)}</Text>)}
          <Text bold>Recent steps</Text>
          {steps.length === 0 ? <Text dimColor>none yet</Text>
            : steps.map(ev => <Text wrap="truncate-end"><Text dimColor>{ago(ev.t)} ago </Text>{ev.tool} {ev.arg ?? ''}</Text>)}
          {detail.key === open.key && detail.report !== undefined && <Text bold>Report</Text>}
          {detail.key === open.key && detail.report !== undefined &&
            <Text wrap="wrap">{detail.report ? detail.report.slice(0, REPORT_CHARS) : 'no report (timed out or killed)'}</Text>}
        </Box>
      )
    }
    if (sel) { selKey = ''; void update($, selected, () => '') }   // the worker left the crew
    if (e.surface !== 'terminal') {
      const { Box, Text, Button, Svg } = $.ui.resolve(e)
      const now = await $.clock.now()
      svgAt = now
      const cols = Math.max(46, Math.min(138, e.props.bodyColumns))
      let { rows, words, spots } = drawScene(workers, cols, now, 256, true)
      const sprites = []
      for (const s of spots) {
        const file = frameFile(s.look)
        let base64 = pngs.get(file)
        if (base64 === undefined) {
          base64 = await $.fs.read(`${$.plugin.root}/frames/${file}`, { as: 'bytes' }).then(r => r.base64, () => '')
          pngs.set(file, base64)
        }
        if (base64) sprites.push({ x: s.x, y: s.y, base64 })
      }
      let svg = sceneSvg(words, cols, rows, sprites)
      // A frame that would not read, or too many sprites for one Svg: half-block pixels instead.
      if (sprites.length < spots.length || svg.length > 131_072) { ({ rows, words } = drawScene(workers, cols, now, 256, false)); svg = sceneSvg(words, cols, rows) }
      const alt = workers.length ? workers.map(w => `${w.name} ${w.role} ${LABEL[w.state]}`).join(', ') : 'no workers'
      return (
        <Box flexDirection="column" gap={1}>
          {svg.length <= 131_072 ? <Svg key="crew" source={svg} alt={alt} />
            : workers.map(w => <Text>{w.name} · {w.role} · {LABEL[w.state]}</Text>)}
          {workers.length > 0 && (
            <Box flexDirection="row" gap={1} flexWrap="wrap">
              {workers.map(w => <Button key={`open-${w.key}`} onPress={() => openDetail($, w.key)}>{w.name} {DETAILS}</Button>)}
            </Box>
          )}
        </Box>
      )
    }
    const { Box, Button, Image, Raster } = $.ui.resolve(e)
    const cols = Math.max(24, Math.min(512, e.props.bodyColumns))
    // Draw every card, even past the pane's height: the engine scrolls a body taller than its window.
    // Only the 256-row hard cap still folds workers into one-line rows.
    const maxRows = 256
    const { rows, words, spots, hits } = drawScene(workers, cols, await $.clock.now(), maxRows, images)
    mounted = { cols, rows, maxRows, images, keys: new Set(spots.map(s => s.key)) }
    const raster = <Raster key="crew" columns={cols} rows={rows} cells={encode(words)} />
    // A "details ›" Button on each card's bottom edge opens its detail view.
    // Not `h`: JSX compiles to the global h(), which a parameter of that name would shadow.
    const buttons = hits.map(hit => (
      <Box position="absolute" top={hit.y} left={hit.x}>
        <Button key={`open-${hit.key}`} plain dimColor onPress={() => openDetail($, hit.key)}>{DETAILS}</Button>
      </Box>
    ))
    if (!images) return <Box width={cols} height={rows}>{raster}{buttons}</Box>
    // Each sprite an Image over the blank cells the scene left for it; paint() swaps its frames.
    shown = new Map(spots.map(s => [s.key, lookKey(s.look)]))
    return (
      <Box width={cols} height={rows}>
        {raster}
        {spots.map(s => (
          <Box position="absolute" top={s.y} left={s.x}>
            <Image key={s.key} source={imageSource(s.look, $.plugin.root)} columns={SPRITE_COLS} rows={SPRITE_ROWS} alt={s.alt} />
          </Box>
        ))}
        {buttons}
      </Box>
    )
  })
}

files.hooks/creatures.ts:
// The crew's creatures: a round owl per scout, a baby dragon per coder (purple and crowned on Opus).
// Drawn in code at 60x32 pixels, 4x the old 15x8 half-block sprites each way, for terminals that
// show images; the same frame downsampled to 15x8 half-blocks for the ones that draw cells only.
// Frames step every FRAME_MS; motion is eased over long loops so nothing jumps more than a pixel or two.

import type { Role, State } from './scene'

export type Pose = State | 'sleep'
export const CLEAR = 0x02000000
export const BIG_W = 60, BIG_H = 32
// Hi-res pixels per logical pixel in the image frames.
export const BIG_S = 2
export const SMALL_W = 15, SMALL_H = 8
export const FRAME_MS = 125
// A see-through black (gen_frames.py writes it with alpha) so the shadow suits any terminal background.
export const SHADOW = 0x03000000

const OUT = 0x2a2140
const EYE = 0x1f1833, IRIS = 0x4a4fa8, SHINE = 0xffffff, BLUSH = 0xff9cc2, TONGUE = 0xff6f91
const TEAR = 0x8fd3ff
const CONFETTI = [0xff6b6b, 0xffd166, 0x06d6a0, 0x4dabf7, 0xcc5de8, 0xffffff]

// Drawn in logical pixels; `s` hi-res pixels per logical one, so curves and outlines come out finer
// while every shape keeps its logical size and place.
export class Canvas {
  px: Uint32Array
  readonly pw: number; readonly ph: number
  constructor(readonly w: number, readonly h: number, readonly s = 1) {
    this.pw = w * s; this.ph = h * s
    this.px = new Uint32Array(this.pw * this.ph).fill(CLEAR)
  }
  at(x: number, y: number) {
    const i = Math.floor(x * this.s + 1e-6), j = Math.floor(y * this.s + 1e-6)
    return i >= 0 && j >= 0 && i < this.pw && j < this.ph ? this.px[j * this.pw + i] ?? CLEAR : CLEAR
  }
  dot(i: number, j: number, c: number, on?: number) {
    if (i < 0 || j < 0 || i >= this.pw || j >= this.ph) return
    if (on !== undefined && this.px[j * this.pw + i] !== on) return
    this.px[j * this.pw + i] = c
  }
  // One logical pixel: an s x s block, placed to the hi-res pixel.
  put(x: number, y: number, c: number, on?: number) {
    const i0 = Math.floor(x * this.s + 1e-6), j0 = Math.floor(y * this.s + 1e-6)
    for (let j = 0; j < this.s; j++) for (let i = 0; i < this.s; i++) this.dot(i0 + i, j0 + j, c, on)
  }
  rect(x: number, y: number, w: number, h: number, c: number) {
    const i0 = Math.floor(x * this.s + 1e-6), j0 = Math.floor(y * this.s + 1e-6)
    for (let j = 0; j < Math.round(h * this.s); j++) for (let i = 0; i < Math.round(w * this.s); i++) this.dot(i0 + i, j0 + j, c)
  }
  // Every hi-res pixel whose centre lies in the ellipse; `keep` (in logical units) limits it to some of them.
  oval(cx: number, cy: number, rx: number, ry: number, c: number, keep?: (x: number, y: number) => boolean) {
    const s = this.s
    for (let j = Math.floor((cy - ry) * s); j <= Math.ceil((cy + ry) * s); j++) {
      for (let i = Math.floor((cx - rx) * s); i <= Math.ceil((cx + rx) * s); i++) {
        const dx = ((i + 0.5) / s - cx) / rx, dy = ((j + 0.5) / s - cy) / ry
        if (dx * dx + dy * dy <= 1 && (!keep || keep(i / s, j / s))) this.dot(i, j, c)
      }
    }
  }
  // An oval with a dark rim of its own, so it reads over a body of a near colour.
  rim(cx: number, cy: number, rx: number, ry: number, c: number) {
    this.oval(cx, cy, rx + 1, ry + 1, OUT)
    this.oval(cx, cy, rx, ry, c)
  }
  tri(ax: number, ay: number, bx: number, by: number, cx: number, cy: number, c: number) {
    const side = (px: number, py: number, x0: number, y0: number, x1: number, y1: number) =>
      (px - x1) * (y0 - y1) - (x0 - x1) * (py - y1)
    const s = this.s
    for (let j = Math.floor(Math.min(ay, by, cy) * s); j <= Math.ceil(Math.max(ay, by, cy) * s); j++) {
      for (let i = Math.floor(Math.min(ax, bx, cx) * s); i <= Math.ceil(Math.max(ax, bx, cx) * s); i++) {
        const px = (i + 0.5) / s, py = (j + 0.5) / s
        const d1 = side(px, py, ax, ay, bx, by), d2 = side(px, py, bx, by, cx, cy), d3 = side(px, py, cx, cy, ax, ay)
        if (!((d1 < 0 || d2 < 0 || d3 < 0) && (d1 > 0 || d2 > 0 || d3 > 0))) this.dot(i, j, c)
      }
    }
  }
  line(x0: number, y0: number, x1: number, y1: number, c: number, thick = 1) {
    const n = Math.max(1, Math.ceil(Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)) * this.s))
    for (let k = 0; k <= n; k++) {
      const x = x0 + ((x1 - x0) * k) / n, y = y0 + ((y1 - y0) * k) / n
      this.rect(x, y, thick, thick, c)
    }
  }
  stamp(rows: string[], pal: Record<string, number>, ox: number, oy: number, k = 1) {
    rows.forEach((row, y) => {
      for (let x = 0; x < row.length; x++) {
        const c = pal[row[x] ?? '.']
        if (c !== undefined) this.rect(ox + x * k, oy + y * k, k, k, c)
      }
    })
  }
  // A one hi-res pixel dark edge around everything drawn so far: the sticker look.
  outline(c: number) {
    const src = this.px.slice(), W = this.pw, H = this.ph
    const at = (x: number, y: number) => (x < 0 || y < 0 || x >= W || y >= H ? CLEAR : src[y * W + x])
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      if (src[y * W + x] !== CLEAR) continue
      if (at(x - 1, y) !== CLEAR || at(x + 1, y) !== CLEAR || at(x, y - 1) !== CLEAR || at(x, y + 1) !== CLEAR) {
        this.px[y * W + x] = c
      }
    }
  }
  over(o: Canvas) {
    for (let i = 0; i < this.px.length; i++) if ((o.px[i] ?? CLEAR) !== CLEAR) this.px[i] = o.px[i] ?? CLEAR
  }
}

const mix = (a: number, b: number, k: number) => {
  const ch = (s: number) => Math.round(((a >> s) & 255) * (1 - k) + ((b >> s) & 255) * k)
  return (ch(16) << 16) | (ch(8) << 8) | ch(0)
}
// One smooth cycle over `n` frames: 0 at frame 0, 1 halfway, back to 0.
const cyc = (f: number, n: number) => 0.5 - 0.5 * Math.cos((2 * Math.PI * f) / n)
const ease = (t: number) => (t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t))
const dim = (c: number) => mix(c, 0x000000, 0.3)
const rnd = (a: number, b: number) => {
  const x = Math.sin(a * 12.9898 + b * 78.233) * 43758.5453
  return x - Math.floor(x)
}

type Pal = {
  body: number; shade: number; light: number; belly: number; mark: number
  wing: number; face: number; beak: number; horn: number
}
const OWL: Pal = {
  body: 0x63c9cf, shade: 0x3d9cad, light: 0xb4f0ea, belly: 0xfff3da, mark: 0xe8cf9f,
  wing: 0x4aa3bd, face: 0xeafaf6, beak: 0xffa938, horn: 0x3d9cad,
}
const DRAGON: Pal = {
  body: 0xffab52, shade: 0xe27c2f, light: 0xffd79c, belly: 0xfff0c8, mark: 0xf0c084,
  wing: 0xff6f5e, face: 0xffab52, beak: 0, horn: 0xfff4dc,
}
const DRAGON_OPUS: Pal = {
  body: 0xb59cff, shade: 0x8a6fe3, light: 0xe0d6ff, belly: 0xfff0fa, mark: 0xe6c6ef,
  wing: 0xff8fcf, face: 0xb59cff, beak: 0, horn: 0xfff4dc,
}

type Arm = 'down' | 'up' | 'wave' | 'hold' | 'type' | 'chin' | 'point'
type Eyes = 'open' | 'wide' | 'closed' | 'happy' | 'dizzy' | 'squeeze' | 'sad'
type Mouth = 'smile' | 'open' | 'o' | 'frown' | 'flat'
type Body = {
  x: number; y: number; squash: number; look: [number, number]
  eyes: Eyes; mouth: Mouth; left: Arm; right: Arm; phase: number
  hat?: 'crown' | 'nightcap' | 'shell'; glasses?: boolean; flap: number
}
type Frame = { cx: number; cy: number; top: number; bottom: number; rx: number; ry: number; eyY: number }

function frameOf(b: Body): Frame {
  const top = 8 + b.y + b.squash, bottom = 30.5 + b.y
  const cy = (top + bottom) / 2, ry = (bottom - top) / 2
  return { cx: 16 + b.x, cy, top, bottom, rx: 12.5 + b.squash * 0.5, ry, eyY: cy - 3.5 }
}

function eye(c: Canvas, x: number, y: number, kind: Eyes, look: [number, number], phase: number, side: number, lid: number) {
  const ix = Math.floor(x), iy = Math.floor(y)
  switch (kind) {
    case 'open':
    case 'wide':
    case 'sad': {
      const r = kind === 'wide' ? 3.5 : 3.1
      const lx = x + look[0], ly = y + look[1]
      c.oval(lx, ly, r, r + 0.6, EYE)
      c.oval(lx, ly + 1.8, r - 0.9, 1.6, IRIS, (px, py) => c.at(px, py) === EYE)
      c.rect(Math.floor(lx - 1.7), Math.floor(ly - 2.3), 2, 2, SHINE)
      c.put(lx + 1.1, ly + 1.2, SHINE)
      if (kind === 'wide') c.put(lx + 1.4, ly - 2.2, SHINE)
      if (kind === 'sad') {
        // a heavy lid slanting down to the outside
        for (let yy = iy - 5; yy <= iy; yy++) for (let xx = ix - 4; xx <= ix + 4; xx++) {
          const cut = iy - 1 + (xx - ix) * side * 0.4
          if (yy < cut) for (const on of [EYE, IRIS, SHINE]) c.put(xx, yy, lid, on)
        }
        c.line(ix - 3, iy - 1 - 3 * side * 0.4, ix + 3, iy - 1 + 3 * side * 0.4, EYE)
      }
      break
    }
    case 'closed':
      for (const [dx, dy] of [[-2, 0], [-1, 1], [0, 1], [1, 1], [2, 0]] as const) c.put(ix + dx, iy + dy, EYE)
      break
    case 'happy':
      for (const [dx, dy] of [[-2, 1], [-2, 2], [-1, 0], [0, -1], [1, 0], [2, 1], [2, 2]] as const) c.put(ix + dx, iy + dy, EYE)
      break
    case 'squeeze':
      for (const [dx, dy] of [[-2, -2], [-1, -1], [0, 0], [-1, 1], [-2, 2], [-1, -2], [0, -1], [1, 0], [0, 1], [-1, 2]] as const) {
        c.put(ix + dx * -side, iy + dy, EYE)
      }
      break
    case 'dizzy':
      for (let t = 0; t < 4 * Math.PI; t += 0.12) {
        const r = 0.3 + t * 0.26
        c.put(x + r * Math.cos(t * side + phase), y + 0.3 + r * Math.sin(t * side + phase), EYE)
      }
      break
  }
}

function body(c: Canvas, role: Role, pal: Pal, b: Body) {
  const { cx, cy, top, bottom, rx, ry, eyY } = frameOf(b)
  if (role === 'coder') {
    // the tail curls out behind, to the right
    const wag = Math.sin((b.phase * Math.PI) / 8) * 0.8
    for (let t = 0; t <= 1.0001; t += 0.05) {
      const r = 3 - 1.7 * t
      c.oval(cx + 8 + 8.5 * t, bottom - 3 - 9 * t * t + wag * t, r, r, pal.body)
    }
    c.tri(cx + 14.5, bottom - 13 + wag, cx + 18.5, bottom - 15 + wag, cx + 17, bottom - 10 + wag, pal.wing)
    // bat wings behind the shoulders
    for (const s of [-1, 1]) {
      c.tri(cx + s * 7, cy - 6, cx + s * 15.6, cy - 12 - b.flap, cx + s * 10, cy + 1, pal.wing)
      c.tri(cx + s * 11, cy - 4, cx + s * 15.6, cy - 12 - b.flap, cx + s * 15, cy - 1, pal.wing)
    }
  } else {
    for (const s of [-1, 1]) c.tri(cx + s * 4.5, top + 3, cx + s * 10.5, top - 4.5, cx + s * 11.5, top + 6, pal.horn)
  }

  c.oval(cx, cy, rx, ry, pal.shade)
  c.oval(cx - 0.6, cy - 0.9, rx - 1.1, ry - 0.9, pal.body)
  c.oval(cx - 6, top + 3.6, 3.6, 1.7, pal.light)
  c.oval(cx, bottom - 5.8, 7.6, 5.4, pal.belly)
  if (role === 'scout') {
    for (const [mx, my] of [[-4, -5], [1, -5], [-2, -2.5], [3, -2.5]] as const) {
      const x = Math.floor(cx + mx), y = Math.floor(bottom + my)
      c.put(x, y, pal.mark); c.put(x + 1, y + 1, pal.mark); c.put(x + 2, y, pal.mark)
    }
    for (const s of [-1, 1]) c.oval(cx + s * 5.5, eyY + 0.4, 5.9, 5.3, pal.face)
  } else {
    for (const dy of [-6.5, -3.5]) c.line(cx - 6, bottom + dy, cx + 5, bottom + dy, pal.mark)
    for (const y of [bottom - 6.5, bottom - 3.5]) for (let x = cx - 8; x <= cx + 8; x++) {
      if (c.at(x, y) === pal.mark && (c.at(x, y - 1) !== pal.belly || c.at(x, y + 1) !== pal.belly)) c.put(x, y, pal.belly)
    }
    for (const s of [-1, 1]) c.tri(cx + s * 4.5, top + 2.2, cx + s * 8.5, top - 5, cx + s * 8.6, top + 2.8, pal.horn)
  }

  // feet
  for (const s of [-1, 1]) {
    if (role === 'scout') c.oval(cx + s * 5, bottom, 2.6, 1.3, pal.beak)
    else c.oval(cx + s * 6, bottom - 0.3, 3, 1.6, pal.shade)
  }

  for (const s of [-1, 1]) c.oval(cx + s * 8.6, eyY + 4.2, 1.8, 1, BLUSH)
  for (const [s, x] of [[-1, cx - 5.5], [1, cx + 5.5]] as const) eye(c, x, eyY, b.eyes, b.look, (b.phase * Math.PI) / 8, s, pal.face)
  if (b.glasses) {
    for (const s of [-1, 1]) {
      const gx = cx + s * 5.5
      c.oval(gx, eyY, 4.9, 4.9, OUT, (x, y) => {
        const dx = x + 0.5 - gx, dy = y + 0.5 - eyY
        return dx * dx + dy * dy > 3.9 * 3.9
      })
    }
    c.line(cx - 1, eyY - 1, cx, eyY - 1, OUT)
  }

  const my = Math.floor(eyY + 3)
  const mx = Math.floor(cx)
  if (role === 'scout') {
    if (b.mouth === 'open' || b.mouth === 'o') {
      c.rect(mx - 2, my, 4, 1, pal.beak); c.rect(mx - 2, my + 1, 4, 2, EYE)
      c.put(mx - 2, my + 1, pal.beak); c.put(mx + 1, my + 1, pal.beak); c.rect(mx - 1, my + 3, 2, 1, pal.beak)
      if (b.mouth === 'open') c.rect(mx - 1, my + 2, 2, 1, TONGUE)
    } else {
      c.rect(mx - 2, my, 4, 1, pal.beak); c.rect(mx - 1, my + 1, 2, 1, pal.beak)
      if (b.mouth === 'frown') c.rect(mx - 1, my + 2, 2, 1, mix(pal.beak, EYE, 0.3))
    }
  } else {
    c.put(mx - 2, my - 1, pal.shade); c.put(mx + 1, my - 1, pal.shade)
    const y = my + 1
    if (b.mouth === 'smile') {
      for (const [dx, dy] of [[-3, 0], [-2, 1], [-1, 0], [0, 0], [1, 1], [2, 0]] as const) c.put(mx + dx, y + dy, EYE)
    } else if (b.mouth === 'open') {
      c.oval(cx, y + 1.2, 2.4, 1.9, EYE)
      c.oval(cx, y + 2.4, 1.6, 0.8, TONGUE, (px, py) => c.at(px, py) === EYE)
      c.put(mx - 2, y, SHINE)
    } else if (b.mouth === 'o') {
      c.oval(cx, y + 0.8, 1.3, 1.4, EYE)
    } else if (b.mouth === 'frown') {
      for (const [dx, dy] of [[-2, 1], [-1, 0], [0, 0], [1, 1]] as const) c.put(mx + dx, y + dy, EYE)
    } else {
      c.rect(mx - 1, y, 2, 1, EYE)
    }
  }

  if (b.hat === 'crown') {
    c.stamp([
      'Y...YY...Y',
      'YY.YYYY.YY',
      'YYYYPPYYYY',
      'yyyyyyyyyy',
    ], { Y: 0xffd447, y: 0xe0a422, P: 0xff5fa2 }, mx - 5, Math.floor(top) - 4)
  } else if (b.hat === 'nightcap') {
    const t = Math.floor(top)
    c.tri(mx - 8, t + 2, mx + 8, t + 2, mx + 11, t - 6, 0x6c7bff)
    c.tri(mx - 2, t - 1, mx + 6, t - 1, mx + 11, t - 6, 0x8f9bff)
    c.rect(mx - 8, t + 1, 17, 2, 0xf4f1ff)
    c.oval(mx + 12, t - 6.5, 2.2, 2.2, 0xf4f1ff)
  } else if (b.hat === 'shell') {
    const t = Math.floor(top)
    // the top of the eggshell, its broken edge jagged
    c.oval(cx, t + 2, 7, 5, 0xfff6e6, (x, y) => y < t + 1 || (y === t + 1 && x % 2 === 0))
    c.oval(cx - 3, t - 1, 1.2, 0.8, pal.body)
  }
}

function arm(c: Canvas, role: Role, pal: Pal, b: Body, side: number, kind: Arm) {
  const { cx, cy, eyY } = frameOf(b)
  // owls have wings, dragons stubby paws: smaller, in the body's shade
  const col = role === 'scout' ? pal.wing : pal.shade
  const k = role === 'scout' ? 1 : 0.75
  const s = side
  const limb = (x: number, y: number, rx: number, ry: number) => c.rim(x, y, rx * k, ry * k, col)
  switch (kind) {
    case 'down': limb(cx + s * (role === 'scout' ? 11.2 : 10), cy + 3, 2.5, 4.8); break
    case 'up': limb(cx + s * 12.4, cy - 8.5, 2.3, 4.5); break
    case 'wave':
      if (b.phase % 8 < 4) limb(cx + s * 12.4, cy - 8.5, 2.3, 4.5)
      else limb(cx + s * 13.8, cy - 7, 2.3, 4.2)
      break
    case 'hold': limb(cx + s * 12.6, cy + 3, 4.6, 2.3); break
    case 'type': limb(cx + s * 12.2, cy + 4.5 - (Math.floor(b.phase / 2) % 2 ? 1.5 : 0), 4.2, 2.2); break
    case 'chin': c.rim(cx + s * 4.5, eyY + 7, 2.2, 1.6, col); break
    case 'point':
      limb(cx + s * 11.5, cy - 2, 2.4, 3.2)
      limb(cx + s * 13.8, cy - 6.5, 2.2, 2.4)
      c.oval(cx + s * 11.5, cy - 2, 2.4 * k, 3.2 * k, col)
      break
  }
}

function sparkle(c: Canvas, x: number, y: number, size: number, col = 0xffffff) {
  if (size <= 0) return
  c.put(x, y, col)
  for (let k = 1; k <= size; k++) {
    const t = k === size ? mix(col, 0x8888aa, 0.35) : col
    c.put(x + k, y, t); c.put(x - k, y, t); c.put(x, y + k, t); c.put(x, y - k, t)
  }
}

function star(c: Canvas, x: number, y: number) {
  c.stamp(['..y..', '.yyy.', 'yyWyy', '.yyy.', '.y.y.'], { y: 0xffe066, W: 0xfffbe0 }, Math.floor(x) - 2, Math.floor(y) - 2)
}

const Z5 = ['#####', '...#.', '..#..', '.#...', '#####']
const Z4 = ['####', '..#.', '.#..', '####']
const QUESTION = ['.###.', '#...#', '...#.', '..#..', '..#..', '.....', '..#..']

// Which frame a state shows at `now`: `seed` puts each worker's loop at its own phase.
// Counts are frames of FRAME_MS. An intro plays once from the state's start; then the loop runs,
// or, with no loop, the intro's last frame holds.
export const LOOP: Record<Pose, number> = {
  boot: 0, resumed: 0, think: 32, read: 48, write: 48, bash: 32, web: 32, test: 32,
  blocked: 16, error: 32, ask: 32, done: 1, failed: 1, sleep: 32,
}
export const INTRO: Partial<Record<Pose, number>> = { boot: 12, resumed: 12, blocked: 8, done: 16, failed: 8 }
export const BLINKS: Pose[] = ['think', 'read', 'write', 'bash', 'web', 'test', 'ask']
// Working creatures breathe on a 2 s cycle; every loop above is a multiple of it.
const BREATHE: Pose[] = ['think', 'read', 'write', 'bash', 'web', 'test', 'ask', 'error', 'blocked']
export type Look = { role: Role; opus: boolean; state: Pose; frame: number; blink: boolean }

export function lookAt(role: Role, model: string, state: Pose, now: number, stateAt: number, seed: number): Look {
  const opus = /opus/i.test(model)
  const tick = Math.floor(now / FRAME_MS) + seed
  const intro = INTRO[state] ?? 0, loop = LOOP[state]
  const step = Math.floor(Math.max(0, now - stateAt) / FRAME_MS)
  const frame = step < intro ? step : loop ? intro + (loop > 1 ? tick % loop : 0) : intro - 1
  const blink = BLINKS.includes(state) && tick % 31 === 0
  return { role, opus, state, frame, blink }
}
export const lookKey = (l: Look) => `${l.role}${l.opus ? '+' : ''}:${l.state}:${l.frame}${l.blink ? 'b' : ''}`
export const frameCount = (state: Pose) => (INTRO[state] ?? 0) + LOOP[state]

export function drawLook({ role, opus, state, frame: f, blink }: Look): Canvas {
  const pal = role === 'scout' ? OWL : opus ? DRAGON_OPUS : DRAGON
  const c = new Canvas(BIG_W, BIG_H, BIG_S)
  const fx = new Canvas(BIG_W, BIG_H, BIG_S)
  const b: Body = {
    x: 0, y: 0, squash: 0, look: [0, 0], eyes: 'open', mouth: 'smile', left: 'down', right: 'down',
    phase: f, hat: opus ? 'crown' : undefined, flap: 0,
  }
  let creature = true
  let mid: () => void = () => {}
  let front: () => void = () => {}

  switch (state) {
    case 'boot': {
      if (f <= 6) {
        creature = false
        const ox = [0, 0, -1, 0, 1, 0, -1][f] ?? 0
        c.oval(16 + ox, 19.5, 10.5, 12.5, 0xfff6e6)
        c.oval(17.5 + ox, 21, 9, 11, 0xf1e2c8, (x, y) => (x - 16 - ox) * 0.6 + (y - 19.5) > 6)
        for (const [x, y, rx, ry] of [[11.5, 14, 2.2, 1.6], [20.5, 23, 2.8, 2.1], [12.5, 26, 1.6, 1.3], [21.5, 12, 1.4, 1.1]] as const) {
          c.oval(x + ox, y, rx, ry, pal.body)
        }
        c.oval(12.5 + ox, 11, 1.4, 2.6, 0xffffff)
        const crack: [number, number][] = [[6, 17], [8, 20], [10, 16], [13, 21], [15, 17], [18, 21], [21, 16], [24, 20], [26, 17]]
        const n = Math.max(0, Math.floor((f - 1) * 1.6))
        for (let i = 0; i < Math.min(n, crack.length - 1); i++) {
          const p = crack[i], q = crack[i + 1]
          if (p && q) c.line(p[0] + ox, p[1], q[0] + ox, q[1], OUT)
        }
        if (f >= 3) for (let i = 0; i < 3; i++) sparkle(fx, 36 + rnd(i, f) * 20, 4 + rnd(f, i) * 22, 1, i % 2 ? pal.body : 0xffffff)
      } else {
        const out = f >= 10
        b.eyes = out ? 'happy' : 'wide'
        b.mouth = out ? 'open' : 'o'
        b.left = out ? 'up' : 'down'; b.right = out ? 'up' : 'down'
        b.y = f === 10 ? -1.5 : f === 11 ? -0.5 : 0
        if (out) b.hat = 'shell'
        front = () => {
          if (!out) {
            // the lower half of the shell still around the belly, the cap flying off up and to the right
            c.oval(16, 23, 12.5, 9, 0xfff6e6, (x, y) => y >= 26 + (x % 2))
            for (let x = 4; x <= 28; x++) c.put(x, 25 + (x % 2), OUT)
            const t = ease((f - 6) / 3)
            const tx = 30 + 16 * t, ty = 9 - 7 * t
            c.oval(tx, ty + 3, 6, 4, 0xfff6e6, (_, y) => y < ty + 4)
            c.oval(tx - 2, ty + 1.5, 1.5, 1, pal.body)
          } else {
            c.oval(40, 29.5, 4, 2.5, 0xfff6e6, (_, y) => y >= 29)
            c.oval(50, 30, 3, 2, 0xfff6e6, (_, y) => y >= 30)
          }
          for (let i = 0; i < 5; i++) sparkle(fx, 34 + rnd(i, f) * 24, 3 + rnd(f, i) * 24, 1 + ((i + f) % 2), [0xffffff, 0xffe066, pal.body][i % 3])
        }
      }
      break
    }

    case 'think': {
      b.look = [0.6 + 0.5 * Math.sin((f * Math.PI) / 16), -1]; b.right = 'chin'; b.mouth = 'flat'
      mid = () => {
        const dy = Math.round(cyc(f, 32))
        for (const [x, y, rx, ry] of [[41.5, 8.5, 5, 4.5], [48, 6.5, 6, 5.2], [54.5, 8.5, 4.6, 4.2], [45, 12, 5.5, 3.2], [51.5, 12, 5.5, 3.2]] as const) {
          c.oval(x, y + dy, rx, ry, 0xf4f1ff)
        }
        c.oval(34.5, 18.5, 1.6, 1.6, 0xf4f1ff)
        c.oval(37.5, 15 + dy * 0.5, 2.2, 2.1, 0xf4f1ff)
        // the dots light one a second, each fading in
        for (let i = 0; i < 3; i++) c.rect(42 + i * 5, 8 + dy, 3, 3, mix(0xd5d0ea, 0x6a5acd, ease((f - 8 * i - 5) / 3)))
      }
      break
    }

    case 'read': {
      // the eyes follow the highlighted line down the left page, then the right, then the page turns
      const line = Math.min(7, Math.floor(f / 5))
      b.look = [line < 4 ? 0.2 : 1.4, 0.4 + (line % 4) * 0.35]; b.glasses = true; b.right = 'hold'; b.mouth = 'flat'
      mid = () => {
        c.rect(31, 16, 27, 14, OUT)
        c.rect(32, 27, 25, 2, 0xc4664d)
        c.rect(32, 17, 12, 10, 0xfffaf0); c.rect(45, 17, 11, 10, 0xfffaf0)
        c.rect(44, 17, 1, 10, 0xd9cbb2); c.rect(43, 17, 1, 10, 0xece2cf)
        for (let i = 0; i < 4; i++) {
          for (const [x0, w0, k] of [[33, 9, 0], [46, 9, 1]] as const) {
            const len = 5 + Math.floor(rnd(i + k * 4, 0) * (w0 - 4))
            c.rect(x0, 18 + i * 2 + 1, len, 1, f < 40 && line === i + k * 4 ? 0x4d9bf0 : 0xa7adbf)
          }
        }
        const turn = f >= 41 && f <= 46 ? Math.floor((f - 41) / 2) : -1
        if (turn >= 0) {
          const x = [46, 43, 35][turn] ?? 46, w = turn === 1 ? 2 : 9, y = turn === 1 ? 10 : 14
          c.rect(x - 1, y - 1, w + 2, 27 - y + 1, OUT)
          c.rect(x, y, w, 27 - y, 0xfff3dd)
        }
      }
      break
    }

    case 'write':
    case 'bash': {
      const code: [number, number, number][][] = [
        [[0, 3, 0xff7aa2], [4, 5, 0x7cc7ff], [10, 2, 0xc9c9e6]],
        [[2, 4, 0x7ee0a1], [7, 6, 0xffd166]],
        [[2, 3, 0xff7aa2], [6, 7, 0x7cc7ff]],
        [[4, 8, 0xc9c9e6], [13, 2, 0xffd166]],
        [[0, 1, 0xc9c9e6]],
      ]
      if (state === 'write') {
        // types the snippet out over ~4 s, then rests with the cursor blinking
        const budget0 = Math.floor(f * 1.25)
        const typing = budget0 < 41
        b.right = typing ? 'type' : 'hold'
        mid = () => {
          c.rect(34, 6, 22, 18, OUT)
          c.rect(35, 7, 20, 16, 0x3b4252)
          c.rect(36, 8, 18, 14, 0x1e2230)
          let budget = budget0
          code.forEach((segs, row) => {
            for (const [x, w, col] of segs) {
              const shown = Math.max(0, Math.min(w, budget))
              budget -= w
              c.rect(37 + x, 10 + row * 2, shown, 1, col)
              if (shown > 0 && shown < w) c.rect(37 + x + shown, 9 + row * 2, 1, 2, 0xffffff)
            }
          })
          if (!typing && f % 8 < 4) c.rect(39, 17, 1, 2, 0xffffff)
          c.rect(31, 24, 28, 5, OUT)
          c.rect(32, 25, 26, 3, 0xc5ccd8)
          for (let x = 33; x < 57; x += 2) c.put(x, 26, 0x8f99aa)
          c.rect(36, 24, 18, 1, 0x8f99aa)
          if (typing) for (let i = 0; i < 3; i++) {
            const ph = (f + i * 5) % 16
            fx.rect(38 + i * 7, 5 - ph * 0.35, 2, 1, [0xff7aa2, 0x7ee0a1, 0x7cc7ff][i] ?? 0xffffff)
          }
        }
        b.look = [1, 0.2 + Math.min(4, Math.floor(budget0 / 9)) * 0.25]
      } else {
        // a line every second scrolls up; the prompt types between them
        const s = Math.floor(f / 8), inLine = f % 8
        const typed = Math.min(3, Math.floor(inLine / 2))
        b.look = [1, 0.6]; b.right = inLine < 6 ? 'type' : 'hold'
        mid = () => {
          c.rect(33, 2, 26, 22, OUT)
          c.rect(34, 3, 24, 3, 0x4c566a)
          c.put(36, 4, 0xff5f56); c.put(38, 4, 0xffbd2e); c.put(40, 4, 0x27c93f)
          c.rect(34, 6, 24, 17, 0x0d1117)
          for (let row = 0; row < 4; row++) {
            const k = (row + s) % 4
            const len = 6 + Math.floor(rnd(k, 3) * 14)
            c.rect(36, 8 + row * 3, len, 1, k % 3 === 0 ? 0x81c784 : 0x8b949e)
          }
          c.stamp(['#..', '.#.', '#..'], { '#': 0x81c784 }, 36, 19)
          c.rect(40, 20, typed * 2, 1, 0xe6edf3)
          if (f % 8 < 4) c.rect(40 + typed * 2, 19, 2, 3, 0xe6edf3)
          c.rect(31, 25, 24, 5, OUT)
          c.rect(32, 26, 22, 3, 0x9aa5b1)
          for (let x = 33; x < 53; x += 2) c.put(x, 27, 0x6b7584)
        }
      }
      break
    }

    case 'web': {
      b.look = [1, -1]; b.right = 'point'; b.mouth = 'o'
      mid = () => {
        const gx = 47, gy = 13, r = 8.5
        c.oval(gx, gy, r + 1, r + 1, OUT)
        c.oval(gx, gy, r, r, 0x3a86ff, (x, y) => {
          const nx = (x + 0.5 - gx) / r, ny = (y + 0.5 - gy) / r
          const lon = Math.asin(Math.max(-1, Math.min(1, nx / Math.sqrt(Math.max(0.0001, 1 - ny * ny))))) + (f * Math.PI) / 16
          const lat = Math.asin(ny)
          const land = Math.sin(lon * 2 + 1) * Math.cos(lat * 2.5) + Math.sin(lon * 3 + lat * 3) * 0.6 > 0.45
          if (land) c.put(x, y, nx > 0.55 ? 0x3a9e5c : 0x52d17c)
          return !land
        })
        c.oval(gx, gy, r, r, 0x2a64c8, (x, y) => c.at(x, y) === 0x3a86ff && (x + 0.5 - gx) / r > 0.55)
        c.rect(gx - 4, gy - 6, 2, 2, 0xd8ecff)
        c.rect(gx - 1, gy + 10, 2, 3, 0x9aa5b1)
        c.rect(gx - 5, gy + 13, 10, 2, 0x9aa5b1)
        const arcs = 1 + Math.min(2, Math.floor((f % 16) / 5))
        for (let k = 0; k < arcs; k++) {
          const rr = 3 + k * 2.5
          const col = k === arcs - 1 ? dim(0x4dd0e1) : 0x4dd0e1
          for (let a = -0.2; a <= Math.PI / 2 + 0.2; a += 0.08) fx.put(gx + 4 + rr * Math.cos(a - Math.PI / 2), gy - 6 + rr * Math.sin(a - Math.PI / 2), col)
        }
      }
      break
    }

    case 'test': {
      // a clipboard of checks ticking green one by one; the row being run pulses yellow
      const row = Math.min(4, Math.floor((f + 1) / 7))
      b.look = [1, -0.4 + Math.min(3, row) * 0.45]; b.glasses = true; b.right = 'hold'; b.mouth = row >= 4 ? 'smile' : 'flat'
      mid = () => {
        c.rect(34, 3, 23, 28, OUT)
        c.rect(35, 4, 21, 26, 0xc68a4f)
        c.rect(37, 7, 17, 21, 0xfffaf0)
        c.rect(41, 1, 9, 4, OUT)
        c.rect(42, 2, 7, 2, 0x9aa5b1)
        for (let i = 0; i < 4; i++) {
          const y = 8 + i * 5
          const done = i < row, now = i === row
          c.rect(38, y, 5, 5, OUT)
          c.rect(39, y + 1, 3, 3, done ? 0xd7f5df : now ? mix(0xfff3c4, 0xffd166, cyc(f, 4)) : 0xffffff)
          if (done) c.stamp(['..#', '#.#', '.#.'], { '#': 0x2e9e4f }, 39, y + 1)
          c.rect(44, y + 2, 5 + Math.floor(rnd(i, 1) * 5), 1, done ? 0x6b7584 : 0xa7adbf)
        }
        if (row >= 4) for (let k = 0; k < 3; k++) sparkle(fx, 36 + rnd(k, 9) * 20, 2 + rnd(9, k) * 6, (f + k) % 3 ? 1 : 2, k % 2 ? 0x7bd88f : 0xffffff)
      }
      break
    }

    case 'resumed': {
      // the answer lands: two little hops under a lighting bulb
      b.eyes = 'wide'; b.mouth = 'open'; b.left = 'up'; b.right = 'up'
      b.y = -2.5 * Math.sin((Math.PI * (f % 6)) / 6)
      b.flap = f % 4 < 2 ? 1 : 0
      mid = () => {
        const gx = 47, gy = 11
        const lit = ease(f / 4)
        c.oval(gx, gy, 7.2, 7.4, mix(0xd8dce6, 0xffe066, lit))
        c.oval(gx + 1.5, gy + 1.5, 5.5, 5.5, mix(0xb8bdca, 0xffd23f, lit), (x, y) => (x - gx) + (y - gy) > 3)
        c.oval(gx - 2.5, gy - 3, 1.4, 2.2, 0xfffbe0)
        c.line(gx - 2, gy + 2, gx - 1, gy + 4, 0xff9f1c); c.line(gx - 1, gy + 4, gx, gy + 2, 0xff9f1c)
        c.line(gx, gy + 2, gx + 1, gy + 4, 0xff9f1c)
        c.rect(gx - 4, gy + 7, 8, 6, OUT)
        c.rect(gx - 3, gy + 7, 6, 5, 0xb0b8c4)
        c.rect(gx - 3, gy + 8, 6, 1, 0x7f889a); c.rect(gx - 3, gy + 10, 6, 1, 0x7f889a)
        const len = f < 3 ? 0 : 1 + Math.min(2, Math.floor((f - 3) / 2))
        for (let k = 0; k < 8; k++) {
          if (k === 2) continue
          const a = (k * Math.PI) / 4 - Math.PI / 2
          for (let d = 0; d < len; d++) fx.put(gx + Math.cos(a) * (10 + d), gy + Math.sin(a) * (10 + d), 0xfff3b0)
        }
      }
      break
    }

    case 'ask': {
      b.eyes = 'wide'; b.look = [1, -1]; b.mouth = 'open'; b.right = 'wave'
      mid = () => {
        const dy = Math.round(cyc(f, 32))
        c.oval(47, 11 + dy, 10, 9.5, 0xfffaf0)
        c.tri(36.5, 13 + dy, 40, 17 + dy, 33, 21 + dy, 0xfffaf0)
        c.stamp(QUESTION, { '#': 0xff9f1c }, 42, 4 + dy, 2)
        const tw = f % 16
        if (tw >= 2 && tw <= 5) sparkle(fx, 57, 2, tw === 3 || tw === 4 ? 2 : 1, 0xffd166)
        if (tw >= 10 && tw <= 12) sparkle(fx, 36, 3, 1, 0xffd166)
      }
      break
    }

    case 'blocked': {
      b.eyes = 'squeeze'; b.mouth = 'frown'
      if (f < 8) b.x = [-1, 1, -1, 1, -0.6, 0.6, -0.3, 0][f] ?? 0
      const g = Math.max(0, f - 8)
      mid = () => {
        const gx = 47, gy = 13
        c.oval(gx, gy, 9, 9, OUT)
        c.oval(gx, gy, 8, 8, f < 8 ? 0xff4d5e : mix(0xd93a4b, 0xff4d5e, cyc(g, 16)))
        c.rect(gx - 6, gy - 1, 12, 3, 0xffffff)
        const fr = frameOf(b)
        const ph = (g + 10) % 16
        fx.oval(fr.cx + 10, fr.top + 3 + ph * 0.35, 1.2, 1.7, TEAR)
        fx.put(fr.cx + 9.6, fr.top + 2 + ph * 0.35, TEAR)
      }
      break
    }

    case 'error': {
      // a slow dizzy spin: half the usual phase rate
      b.eyes = 'dizzy'; b.mouth = 'flat'; b.phase = f / 2
      b.x = 0.8 * Math.sin((2 * Math.PI * f) / 32)
      mid = () => {
        c.tri(47, 3, 36, 22.5, 58, 22.5, OUT)
        c.tri(47, 5.5, 38, 21.5, 56, 21.5, mix(0xff9f43, 0xffc078, cyc(f, 32)))
        c.rect(46, 10, 2, 6, OUT); c.rect(46, 17, 2, 2, OUT)
        const fr = frameOf(b)
        for (let k = 0; k < 3; k++) {
          const a = (f * Math.PI) / 16 + (k * 2 * Math.PI) / 3
          star(fx, fr.cx + 11 * Math.cos(a), fr.top - 0.5 + 2.2 * Math.sin(a))
        }
      }
      break
    }

    case 'done': {
      if (f < 16) {
        // two hops, a squash on each landing, confetti drifting down
        const h = f % 8
        b.eyes = 'happy'; b.mouth = 'open'; b.left = 'up'; b.right = 'wave'
        b.y = -3 * Math.sin((Math.PI * h) / 8)
        b.squash = h === 0 ? 1 : 0
        b.flap = f % 4 < 2 ? 2 : 0
        front = () => {
          for (let i = 0; i < 16; i++) {
            const x = rnd(i, 7) * 60 + Math.sin((f + i) * 0.6) * 1.2, y = (rnd(i, 3) * 32 + f) % 32
            const col = CONFETTI[i % CONFETTI.length] ?? 0xffffff
            if ((i + Math.floor(f / 2)) % 2) fx.rect(x, y, 2, 1, col)
            else fx.rect(x, y, 1, 2, col)
          }
        }
      } else {
        b.eyes = 'happy'; b.mouth = 'smile'
        mid = () => {
          const gx = 46, gy = 15
          c.oval(gx, gy, 8, 8, 0x5cd67a)
          c.oval(gx + 1, gy + 1, 6.5, 6.5, 0x43bd62, (x, y) => (x - gx) + (y - gy) > 4)
          c.line(41, 15, 44, 18, 0xffffff, 2); c.line(44, 18, 50, 11, 0xffffff, 2)
          sparkle(fx, 56, 4, 2, 0xffffff); sparkle(fx, 36, 5, 1, 0xfff3b0)
        }
      }
      break
    }

    case 'failed': {
      // sinks down over a second, then holds
      b.eyes = 'sad'; b.mouth = 'frown'; b.squash = ease(Math.min(f, 7) / 7)
      mid = () => {
        const gx = 46, gy = 15
        c.oval(gx, gy, 8, 8, 0xff5c6c)
        c.oval(gx + 1, gy + 1, 6.5, 6.5, 0xe5485a, (x, y) => (x - gx) + (y - gy) > 4)
        c.line(42, 11, 49, 18, 0xffffff, 2); c.line(49, 11, 42, 18, 0xffffff, 2)
        const fr = frameOf(b)
        for (const [s, off] of [[-1, 0], [1, 3]] as const) {
          const ph = Math.min(f, 7 + off) - off
          if (ph >= 0) fx.rect(fr.cx + s * 5.5 + (s < 0 ? -3 : 2), fr.eyY + 3 + Math.min(ph, 4) * 0.8, 1, 2, TEAR)
        }
      }
      break
    }

    case 'sleep': {
      b.eyes = 'closed'; b.mouth = 'o'; b.hat = 'nightcap'
      b.squash = 0.2 + 0.9 * cyc(f, 32)
      front = () => {
        const fr = frameOf(b)
        const r = 0.9 + 2.2 * cyc(f, 32)
        fx.oval(fr.cx + 4.5, fr.eyY + 6.5 - r * 0.3, r, r, 0xbfe9ff)
        fx.put(fr.cx + 4 - r * 0.4, fr.eyY + 5.5 - r * 0.6, 0xffffff)
        for (let k = 0; k < 3; k++) {
          const p = ((f + k * 11) % 32) / 32
          const col = mix(0xc6b3ff, 0x2a2d3d, p * 0.9)
          fx.stamp(k === 0 ? Z4 : Z5, { '#': col }, Math.floor(35 + k * 7 + p * 4), Math.floor(21 - k * 7 - p * 5))
        }
      }
      break
    }
  }

  if (BREATHE.includes(state)) b.squash += 0.7 * cyc(f, 16)
  if (blink && (b.eyes === 'open' || b.eyes === 'wide')) b.eyes = 'closed'
  if (creature) {
    body(c, role, pal, b)
    mid()
    arm(c, role, pal, b, -1, b.left)
    arm(c, role, pal, b, 1, b.right)
    front()
  }
  c.outline(OUT)
  c.over(fx)
  // A soft shadow that shrinks as the creature leaves the ground.
  const out = new Canvas(BIG_W, BIG_H, BIG_S)
  const lift = Math.max(0, -b.y)
  out.oval(creature ? frameOf(b).cx : 16, 31.2, 11.5 - lift * 1.4, 1.6, SHADOW)
  out.over(c)
  return out
}

// ---------- the half-block fallback: 15x8, a small hand-made creature and the props as icons ----------

const SMALL_BODY: Record<Role, string[]> = {
  scout: [
    '.h....h.',
    '.hBBBBh.',
    'BFFBBFFB',
    'BFFBBFFB',
    'BBByyBBB',
    'WBccccBW',
    'WBccccBW',
    '..o..o..',
  ],
  coder: [
    'H......H',
    'wHBBBBHw',
    'wBBBBBBw',
    '.BBBBBB.',
    '.BBBBBB.',
    '.BccccBt',
    '.BccccBt',
    '..d..d..',
  ],
}

const ICON = {
  ask: ['.##.', '#..#', '..#.', '.#..', '....', '.#..'],
  bang: ['#', '#', '#', '.', '#'],
  check: ['....#', '...#.', '#.#..', '.#...'],
  cross: ['#...#', '.#.#.', '..#..', '.#.#.', '#...#'],
  bulb: ['.###.', '#####', '#####', '.###.', '.###.'],
  globe: ['.###.', '#####', '#####', '#####', '.###.'],
  bubble: ['.#####.', '#######', '.#####.'],
  stop: ['.###.', '#####', '#...#', '#####', '.###.'],
  warn: ['..#..', '.###.', '.#.#.', '#####'],
  z: ['###', '..#', '.#.', '###'],
}
const LAND = ['01100011', '11110011', '01110001', '00110110', '00011100']

export function drawSmall({ role, opus, state, frame: big, blink }: Look): Canvas {
  // The icons keep their own short cycles at half the big frames' rate.
  const f = state === 'boot' ? (big < 7 ? Math.floor((big * 5) / 7) : big < 10 ? 5 : 7)
    : state === 'done' ? (big < 16 ? big >> 1 : 8)
    : big >> 1
  const p = new Canvas(SMALL_W, SMALL_H)
  const pal = role === 'scout' ? OWL : opus ? DRAGON_OPUS : DRAGON
  const theme = role === 'scout' ? 0x4fd1c5 : opus ? 0xb59cff : 0xffb347
  const colors: Record<string, number> = {
    h: pal.horn, H: pal.horn, B: pal.body, F: pal.face, y: pal.beak, c: pal.belly, o: pal.beak,
    w: pal.wing, t: pal.body, d: pal.shade,
  }
  const celebrating = state === 'done' && f < 8
  const ox = state === 'blocked' && f < 2 ? f : 0
  const oy = celebrating && f % 4 >= 1 && f % 4 <= 3 ? -1 : 0

  if (state === 'boot' && f < 5) {
    // the egg, cracking
    p.stamp(['..##..', '.####.', '######', '######', '######', '.####.'], { '#': 0xfff6e6 }, 1 + (f === 1 ? -1 : f === 3 ? 1 : 0), 1)
    p.put(2, 3, pal.body); p.put(5, 5, pal.body)
    if (f >= 2) for (let x = 1; x < 1 + (f - 1) * 2 && x < 7; x++) p.put(x, 3 + (x % 2), OUT)
    if (f >= 2) p.put(9 + (f * 3) % 5, (f * 5) % 7, 0xffffff)
    return p
  }

  p.stamp(SMALL_BODY[role], colors, ox, oy)
  if (opus) { p.put(ox + 3, oy, 0xffd447); p.put(ox + 4, oy, 0xffd447) }
  if (state === 'sleep') { p.put(ox + 2, oy, 0x6c7bff); p.put(ox + 3, oy, 0x6c7bff); p.put(ox + 4, oy, 0x6c7bff); p.put(ox + 5, oy, 0xf4f1ff) }
  if (state === 'boot') { p.put(ox + 2, oy, 0xfff6e6); p.put(ox + 3, oy, 0xfff6e6); p.put(ox + 4, oy, 0xfff6e6); p.put(ox + 5, oy, 0xfff6e6) }

  // eyes: one dark pixel each, a lid line when shut
  const eyeRow = oy + 3
  const shut = blink || state === 'sleep' || state === 'blocked' || (state === 'done') || (state === 'boot' && f === 7)
  const up = state === 'think' || state === 'ask' || state === 'web' || state === 'resumed'
  const dx = state === 'read' || state === 'write' || state === 'bash' || state === 'test' ? 1 : 0
  for (const x of [2, 5]) {
    if (state === 'error') p.put(ox + x, eyeRow, f % 2 ? 0xff8a65 : EYE)
    else if (shut) { p.put(ox + x - 1, eyeRow, EYE); p.put(ox + x, eyeRow, EYE) }
    else p.put(ox + x + (x === 2 ? dx : 0) - (x === 5 && dx ? 0 : 0), eyeRow - (up ? 1 : 0), EYE)
    if (state === 'failed') p.put(ox + x, eyeRow + 1 + (f % 2), TEAR)
  }
  if (state !== 'failed' && role === 'coder') { p.put(ox + 1, oy + 4, BLUSH); p.put(ox + 6, oy + 4, BLUSH) }
  if (role === 'coder' && (state === 'done' || state === 'ask' || state === 'resumed')) { p.put(ox + 3, oy + 4, EYE); p.put(ox + 4, oy + 4, EYE) }

  const limb = role === 'scout' ? pal.wing : pal.shade
  const armUp = (x: number) => { p.put(ox + x, oy + 2, limb); p.put(ox + x, oy + 3, limb) }
  const armDown = (x: number) => { p.put(ox + x, oy + 5, limb); p.put(ox + x, oy + 6, limb) }
  armDown(0)

  switch (state) {
    case 'write':
    case 'bash': {
      p.put(7, 5 - (f % 2), limb)
      if (state === 'bash') {
        for (let y = 0; y < 6; y++) for (let x = 9; x < 15; x++) p.put(x, y, y === 0 ? 0x4c566a : 0x0d1117)
        p.put(10, 2, 0x81c784); p.put(11, 3, 0x81c784); p.put(10, 4, 0x81c784)
        if (f % 2 === 0) p.put(13, 4, 0xe6edf3)
        for (let x = 9; x < 14; x++) p.put(x, 7, 0x9aa5b1)
      } else {
        for (let y = 1; y < 6; y++) for (let x = 9; x < 15; x++) p.put(x, y, y === 1 || x === 9 || x === 14 ? 0x3b4252 : 0x1e2230)
        for (let i = 0; i < 3; i++) p.put(10 + i, 2 + i, [0xff7aa2, 0x7ee0a1, 0x7cc7ff][(i + f) % 3] ?? theme)
        for (let x = 8; x < 15; x++) p.put(x, 6, 0xc5ccd8)
        p.put(10 + (f % 4), 0, theme)
      }
      break
    }
    case 'read':
      p.put(7, 5, limb)
      for (let y = 3; y <= 7; y++) for (let x = 8; x <= 14; x++) p.put(x, y, x === 11 ? 0xd9cbb2 : 0xfffaf0)
      for (const y of [4, 6]) {
        const hot = Math.floor(f / 4) % 2
        p.put(9, y, hot && y === 4 ? 0x4d9bf0 : 0xa7adbf); p.put(12, y, 0xa7adbf); p.put(13, y, y === 6 && !hot ? 0x4d9bf0 : 0xa7adbf)
      }
      break
    case 'test':
      p.put(7, 5, limb)
      for (let y = 1; y < 8; y++) for (let x = 9; x < 15; x++) p.put(x, y, x === 9 || x === 14 || y === 1 || y === 7 ? 0xc68a4f : 0xfffaf0)
      p.put(11, 0, 0x9aa5b1); p.put(12, 0, 0x9aa5b1)
      for (let i = 0; i < 3; i++) {
        const y = 2 + i * 2
        p.put(10, y, f % 4 > i ? 0x43bd62 : f % 4 === i ? 0xffd166 : 0xa7adbf)
        p.put(11, y, 0xa7adbf); p.put(12, y, 0xa7adbf)
      }
      break
    case 'web':
      armUp(7)
      ICON.globe.forEach((row, y) => {
        for (let x = 0; x < row.length; x++) if (row[x] === '#') {
          const land = LAND[y]?.[(x + f) % 8] === '1'
          p.put(9 + x, 1 + y, land ? 0x52d17c : 0x3a86ff)
        }
      })
      p.put(f % 4 < 2 ? 14 : 13, 0, 0x4dd0e1)
      break
    case 'ask':
      if (f % 4 < 2) armUp(7); else { p.put(7, 1, limb); p.put(7, 2, limb) }
      p.stamp(ICON.ask, { '#': 0xffd166 }, 10, f % 4 < 2 ? 0 : 1)
      break
    case 'resumed':
      armUp(7); armUp(0)
      p.stamp(ICON.bulb.slice(0, 3), { '#': 0xffe066 }, 10, 0)
      p.stamp(ICON.bulb.slice(3), { '#': 0x9aa5b1 }, 10, 3)
      if (f % 2) { p.put(9, 0, 0xfff3b0); p.put(14, 1, 0xfff3b0); p.put(9, 2, 0xfff3b0) }
      break
    case 'blocked':
      armDown(7)
      p.stamp(ICON.stop, { '#': f < 2 || f % 4 < 2 ? 0xff4d5e : 0xd93a4b }, 10, 1)
      p.put(12, 3, 0xffffff); p.put(11, 3, 0xffffff); p.put(13, 3, 0xffffff)
      p.put(ox + 7, 1 + (f % 3), TEAR)
      break
    case 'error':
      armDown(7)
      p.stamp(ICON.warn, { '#': 0xff9f43 }, 10, 2)
      p.put(12, 3, OUT)
      p.put(ox + 1 + (f % 6), 0, 0xffe066)
      break
    case 'done':
      if (celebrating) {
        armUp(0); armUp(7)
        for (let i = 0; i < 10; i++) {
          const x = Math.floor(rnd(i, 7) * 15), y = Math.floor((rnd(i, 3) * 8 + f) % 8)
          if (p.at(x, y) === CLEAR) p.put(x, y, CONFETTI[i % CONFETTI.length] ?? 0xffffff)
        }
      } else {
        armDown(7)
        p.stamp(ICON.check, { '#': 0x7bd88f }, 10, 2)
        if (f % 16 < 2) p.put(14, 0, 0xffffff)
      }
      break
    case 'failed':
      armDown(7)
      p.stamp(ICON.cross, { '#': 0xff5c6c }, 10, 1)
      break
    case 'sleep': {
      armDown(7)
      p.stamp(ICON.z, { '#': 0xb39ddb }, 9, 4)
      if (f % 8 >= 3) p.stamp(ICON.z, { '#': 0x8f7fbf }, 12, 0)
      break
    }
    case 'boot':
      armUp(0); armUp(7)
      p.put(10, 6, 0xfff6e6); p.put(11, 7, 0xfff6e6); p.put(12, 7, 0xfff6e6)
      p.put(9 + (f % 3) * 2, 1, 0xffffff)
      break
    default: {
      // think: paw at the chin, a thought bubble filling dot by dot
      p.put(6, 4, limb)
      p.put(8, 3, 0xe6e6f0)
      p.stamp(ICON.bubble, { '#': 0xf4f1ff }, 8, 0)
      const lit = Math.floor(f / 4)
      for (let i = 0; i < 3; i++) p.put(9 + i * 2, 1, i < lit ? 0x6a5acd : 0xc8c8d8)
    }
  }
  return p
}

// Frames are pure in their Look, so each is drawn once; a long session sees a few hundred.
const BIG = new Map<string, Canvas>()
const SMALL = new Map<string, Canvas>()
const cached = <T>(m: Map<string, T>, key: string, make: () => T): T => {
  const hit = m.get(key)
  if (hit) return hit
  if (m.size > 800) m.clear()
  const v = make()
  m.set(key, v)
  return v
}
export const bigSprite = (l: Look) => cached(BIG, lookKey(l), () => drawLook(l))
export const smallSprite = (l: Look) => cached(SMALL, lookKey(l), () => drawSmall(l))

// Every distinct frame is a small PNG under frames/ (made by tools/gen_frames.sh); the terminal reads the
// file itself and a source equal to the last one sends nothing, so a blit carries only a path.
export const frameFile = (l: Look) => `${l.role}${l.opus ? '_opus' : ''}-${l.state}-${l.frame}${l.blink ? 'b' : ''}.png`
export const imageSource = (l: Look, root: string) => ({ file: `${root}/frames/${frameFile(l)}`, format: 'png' as const })

export const ALL_POSES: Pose[] = [
  'boot', 'resumed', 'think', 'read', 'write', 'bash', 'web', 'test', 'blocked', 'error', 'ask', 'done', 'failed', 'sleep',
]

files.hooks/scene.ts:
// Pure drawing: cw run files -> worker states -> one Raster of text and half-block pixel art,
// or of text alone with each sprite listed for an Image laid over it.

import { CLEAR, FRAME_MS, SMALL_H, SMALL_W, lookAt, smallSprite, type Canvas, type Look } from './creatures'

export type Role = 'scout' | 'coder'
export type Kind = 'read' | 'write' | 'bash' | 'web'
export type State =
  | 'boot' | 'resumed' | 'think' | Kind | 'test' | 'blocked' | 'error' | 'ask' | 'done' | 'failed'

export type Ev = {
  e: string; t: number; tool?: string; arg?: string
  ok?: boolean; sub?: string; sid?: string; turns?: number; denied?: number; out?: number
}
export type Meta = {
  role: Role; model: string; session: string; resume: string; task: string
  start: number; tmo: number; web: boolean; pid: number; effort?: string; effort_src?: string
  name?: string   // fleet name from cwgo (CW_NAME): shown instead of a generated one
}
export type Run = { id: string; meta: Meta; events: Ev[]; rc?: number; doneAt?: number; question?: string }

export type Worker = {
  key: string; role: Role; model: string; name: string; task: string; effort: string
  start: number; runStart: number; resumed: boolean
  state: State; stateAt: number; arg: string; trail: Kind[]; times: number[]; lastAt: number; tmo: number
  blocked: number; question?: string; end?: number; turns: number; out: number
  runIds: string[]   // the chain's runs, oldest first: the detail view reads their files
}

const NAMES: Record<Role, string[]> = {
  scout: ['KIRI', 'SORA', 'MOCHI', 'YUZU', 'HOSHI', 'NORI', 'TOFU', 'MISO', 'KOJI', 'UME'],
  coder: ['BOLT', 'RIVET', 'PIXEL', 'FORGE', 'GIZMO', 'BYTE', 'FLUX', 'SPARK', 'COG', 'WELD'],
}

const READ_CMD = /^\s*(rg|fd|eza|ls|wc|head|tail|cat|bat|grep|find|sed -n|git (log|show|diff|status|blame))\b/

export function kindOf(tool: string, arg: string): Kind {
  if (tool === 'Read' || tool === 'Grep' || tool === 'Glob') return 'read'
  if (tool === 'Edit' || tool === 'Write' || tool === 'MultiEdit' || tool === 'NotebookEdit') return 'write'
  if (tool === 'WebFetch' || tool === 'WebSearch') return 'web'
  return READ_CMD.test(arg) ? 'read' : 'bash'
}

export function parseEvents(text: string): Ev[] {
  const out: Ev[] = []
  for (const line of text.split('\n')) {
    if (!line.trim()) continue
    try { out.push(JSON.parse(line)) } catch { /* a half-written last line; read again next poll */ }
  }
  return out
}

type RunView = Pick<Worker, 'state' | 'stateAt' | 'arg' | 'blocked' | 'end' | 'turns' | 'out' | 'lastAt'> & { trail: Kind[]; times: number[] }

const ACCEPT_MS = 1_830_000   // cw's CW_ACCEPT_TMO default (1800 s) plus slack

export function runState(run: Run, now: number): RunView {
  const start = run.meta.start * 1000
  const trail: Kind[] = [], times: number[] = []
  let arg = '', lastTool: Ev | undefined, lastDenied: Ev | undefined, lastError: Ev | undefined
  let result: Ev | undefined, accept: Ev | undefined, accepted: Ev | undefined, blocked = 0
  for (const ev of run.events) {
    if (ev.e === 'tool') {
      lastTool = ev
      arg = ev.arg ?? ''
      trail.push(kindOf(ev.tool ?? '', arg))
      times.push(ev.t)
    } else if (ev.e === 'denied') { lastDenied = ev; blocked++ }
    else if (ev.e === 'error') lastError = ev
    else if (ev.e === 'result') result = ev
    else if (ev.e === 'accept') accept = ev
    else if (ev.e === 'accept_end') accepted = ev
  }
  const lastAt = run.events[run.events.length - 1]?.t ?? start
  const base = { arg, trail, times, blocked, lastAt, turns: result?.turns ?? 0, out: result?.out ?? 0 }
  // cw auto-continues a turn-limited run without writing .done: that result is not the end
  const continuing = result?.sub === 'error_max_turns' && run.rc === undefined
  // cw runs the acceptance command after the result and writes .done only when it ends
  if (accept && !accepted && run.rc === undefined && now - accept.t < ACCEPT_MS) {
    return { ...base, state: 'test', stateAt: accept.t }
  }
  if ((result && !continuing) || run.rc !== undefined) {
    const end = accepted?.t ?? result?.t ?? run.doneAt ?? now
    const ok = !!result?.ok && (run.rc ?? 0) === 0 && accepted?.ok !== false
    const state: State = run.question && ok ? 'ask' : ok ? 'done' : 'failed'
    return { ...base, state, stateAt: end, end }
  }
  if (now > start + (run.meta.tmo + 30) * 1000) return { ...base, state: 'failed', stateAt: now, end: now }
  const last = run.events[run.events.length - 1]
  if (run.meta.resume && now - start < 1600) return { ...base, state: 'resumed', stateAt: start }
  if (!last || now - start < 1500) return { ...base, state: 'boot', stateAt: start }
  if (lastDenied && now - lastDenied.t < 4000) return { ...base, state: 'blocked', stateAt: lastDenied.t }
  if (lastError && now - lastError.t < 2500) return { ...base, state: 'error', stateAt: lastError.t }
  if (lastTool && (last === lastTool || now - lastTool.t < 1500)) {
    return { ...base, state: trail[trail.length - 1] ?? 'bash', stateAt: lastTool.t }
  }
  return { ...base, state: 'think', stateAt: last.t }
}

// One worker per chain of runs: a run started with `-r <sid>` continues the worker whose run ended with that sid.
export function buildWorkers(runs: Run[], now: number): Worker[] {
  const sorted = [...runs].sort((a, b) => a.meta.start - b.meta.start || a.id.localeCompare(b.id))
  const bySid = new Map<string, Worker>()
  const workers: Worker[] = []
  const used: Record<Role, number> = { scout: 0, coder: 0 }
  for (const run of sorted) {
    const view = runState(run, now)
    const prev = run.meta.resume ? bySid.get(run.meta.resume) : undefined
    const role = run.meta.role === 'coder' ? 'coder' : 'scout'
    // A resume started under its own fleet name (cwgo NAME -r sid) is a new job on the same creature:
    // show that name, task and clock, as cwls does.
    const renamed = !!prev && !!run.meta.name && run.meta.name !== prev.name
    const w: Worker = {
      key: prev?.key ?? run.id,
      role,
      model: run.meta.model,
      effort: run.meta.effort ?? '',
      name: renamed ? run.meta.name! : prev?.name ?? (run.meta.name || NAMES[role][used[role]++ % NAMES[role].length] + (used[role] > 10 ? String(Math.ceil(used[role] / 10)) : '')),
      task: renamed ? run.meta.task : prev?.task ?? run.meta.task,
      start: renamed ? run.meta.start * 1000 : prev?.start ?? run.meta.start * 1000,
      runStart: run.meta.start * 1000,
      tmo: run.meta.tmo,
      resumed: !!prev,
      ...view,
      trail: [...(prev?.trail ?? []), ...view.trail],
      times: [...(prev?.times ?? []), ...view.times],
      blocked: (prev?.blocked ?? 0) + view.blocked,
      turns: (prev?.turns ?? 0) + view.turns,
      out: (prev?.out ?? 0) + view.out,
      question: view.state === 'ask' ? run.question : undefined,
      runIds: [...(prev?.runIds ?? []), run.id],
    }
    const at = prev ? workers.indexOf(prev) : -1
    if (at >= 0) workers[at] = w
    else workers.push(w)
    // A run that dies before its result (killed, timeout) never maps its sid, so the next resume
    // of the same sid still finds `prev`; point it at the newest run or two workers share a key.
    if (prev) for (const [k, v] of bySid) if (v === prev) bySid.set(k, w)
    // init carries the sid too, so a run that timed out before its result still chains its resume.
    const sid = [...run.events].reverse().find(ev => ev.sid)?.sid
    if (sid) bySid.set(sid, w)
  }
  return workers
}

export const KEEP_MS = 120_000
export const isVisible = (w: Worker, now: number) =>
  w.end === undefined || w.state === 'ask' || now - w.end < KEEP_MS
export const isActive = (w: Worker) => w.end === undefined

// ---------- pixels ----------

const DEF = 0x01000000
// A sprite fills MW x MH cells: one 60x32 Image where the terminal shows pictures, else
// 15x8 half-block pixels (one pixel = one half-block, no scaling). Creature left, props right.
const MW = SMALL_W, MH = SMALL_H / 2

export const THEME: Record<Role, number> = { scout: 0x4fd1c5, coder: 0xffb347 }
const OPUS_THEME = 0xb59cff

const hash = (s: string) => {
  let h = 7
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0
  return h % 997
}
const dim = (c: number, k: number) =>
  (Math.round(((c >> 16) & 255) * k) << 16) | (Math.round(((c >> 8) & 255) * k) << 8) | Math.round((c & 255) * k)
const mix = (a: number, b: number, k: number) => {
  const ch = (s: number) => Math.round(((a >> s) & 255) * (1 - k) + ((b >> s) & 255) * k)
  return (ch(16) << 16) | (ch(8) << 8) | ch(0)
}
// 0..1..0 once every `ms`: colours breathe instead of blinking.
const pulse = (now: number, ms: number) => 0.5 - 0.5 * Math.cos((2 * Math.PI * (now % ms)) / ms)

// Where a sprite goes in the scene: `key` names its Image, `look` the frame it shows.
export type Spot = { key: string; x: number; y: number; look: Look; alt: string }
export const SPRITE_COLS = MW, SPRITE_ROWS = MH

// ---------- cells ----------

export class Grid {
  glyph: Uint32Array; fg: Uint32Array; bg: Uint32Array
  constructor(public w: number, public h: number) {
    this.glyph = new Uint32Array(w * h).fill(0x20)
    this.fg = new Uint32Array(w * h).fill(DEF)
    this.bg = new Uint32Array(w * h).fill(DEF)
  }
  // No `bg`: the cell keeps the one it has, so text and pixels sit on a filled panel.
  put(x: number, y: number, ch: string, fg: number, bg?: number) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return
    const i = y * this.w + x
    this.glyph[i] = ch.codePointAt(0) ?? 0x20
    this.fg[i] = fg
    if (bg !== undefined) this.bg[i] = bg
  }
  fill(x: number, y: number, w: number, h: number, bg: number) {
    for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) this.put(i, j, ' ', DEF, bg)
  }
  text(x: number, y: number, s: string, fg: number, max = this.w - x, bg?: number) {
    const chars = [...s]
    for (let i = 0; i < Math.min(chars.length, max); i++) this.put(x + i, y, chars[i] ?? ' ', fg, bg)
    return Math.max(0, Math.min(chars.length, max))
  }
  // A rounded chip: half-circle caps around the text, the text on the chip's colour.
  pill(x: number, y: number, s: string, fg: number, bg: number, max = this.w - x) {
    if (max < 3) return 0
    this.put(x, y, '▐', bg)
    const n = this.text(x + 1, y, s, fg, max - 2, bg)
    this.put(x + 1 + n, y, '▌', bg)
    return n + 2
  }
  pixels(p: Canvas, x0: number, y0: number) {
    for (let r = 0; r < p.h / 2; r++) for (let x = 0; x < p.w; x++) {
      const top = p.px[r * 2 * p.w + x] ?? CLEAR, bot = p.px[(r * 2 + 1) * p.w + x] ?? CLEAR
      if (top === CLEAR && bot === CLEAR) continue
      if (top === CLEAR) this.put(x0 + x, y0 + r, '▄', bot)
      else if (bot === CLEAR) this.put(x0 + x, y0 + r, '▀', top)
      else if (top === bot) this.put(x0 + x, y0 + r, '█', top)
      else this.put(x0 + x, y0 + r, '▀', top, bot)
    }
  }
  words(): Uint32Array {
    const out = new Uint32Array(this.w * this.h * 3)
    for (let i = 0; i < this.w * this.h; i++) {
      out[i * 3] = this.glyph[i] ?? 0x20; out[i * 3 + 1] = this.fg[i] ?? DEF; out[i * 3 + 2] = this.bg[i] ?? DEF
    }
    return out
  }
}

export const encode = (words: Uint32Array): string =>
  (new Uint8Array(words.buffer) as Uint8Array & { toBase64(): string }).toBase64()

export const LABEL: Record<State, string> = {
  boot: 'waking up', resumed: 'answered', think: 'thinking', read: 'reading', write: 'writing',
  bash: 'command', web: 'on the web', test: 'testing', blocked: 'blocked', error: 'error', ask: 'asking',
  done: 'done', failed: 'failed',
}
export const STATE_COLOR: Record<State, number> = {
  boot: 0xffffff, resumed: 0xffe082, think: 0xb39ddb, read: 0x64b5f6, write: 0xffb347, bash: 0x81c784,
  web: 0x4dd0e1, test: 0x9be7ff, blocked: 0xff6b6b, error: 0xff8a65, ask: 0xffd166, done: 0x7bd88f, failed: 0xff5c5c,
}
const KIND_COLOR: Record<Kind, number> = { read: 0x64b5f6, write: 0xffb347, bash: 0x81c784, web: 0x4dd0e1 }
const EFFORT: Record<string, [number, number]> = { low: [1, 0x81c784], medium: [2, 0xffd166], high: [3, 0xff8a65] }
const SPIN = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'
const TEXT = 0xe6e6f0, DIM = 0x8a8fa3, FAINT = 0x4a4e5c
// Everything sits on the terminal's own background (an Image's cells always show it); this is only
// what chips and fades mix toward, a neutral dark grey close to most dark themes.
const BASE = 0x262626
const EDGE = 0x3c3f4c
const BUCKET_MS = 4000
const QUIET_MS = 45_000

export const CARD_H = 6
const HEADER_H = 2
const EMPTY_H = 8

export const perRow = (cols: number) => Math.max(1, Math.min(3, Math.floor(cols / 46)))

// The engine scrolls a pane body taller than its window; past 256 rows the scene folds:
// as many full cards as fit, the rest as one-line rows, then a "+N" row.
export type Layout = { rows: number; cards: number; lines: number; more: number }
export function layout(n: number, cols: number, maxRows = 256): Layout {
  const cap = Math.max(1, Math.min(256, maxRows))
  const per = perRow(cols)
  const full = HEADER_H + (n === 0 ? EMPTY_H : Math.ceil(n / per) * CARD_H)
  if (full <= cap || n === 0) return { rows: Math.min(full, cap), cards: n, lines: 0, more: 0 }
  for (let k = Math.ceil(n / per) - 1; k >= 0; k--) {
    const cards = Math.min(n, k * per)
    const lines = Math.ceil((n - cards) / per)
    const rows = HEADER_H + k * CARD_H + lines
    if (rows <= cap) return { rows, cards, lines, more: 0 }
  }
  const lines = Math.max(0, cap - HEADER_H - 1)
  return { rows: cap, cards: 0, lines, more: n - lines * per }
}
export const sceneRows = (n: number, cols: number, maxRows?: number) => layout(n, cols, maxRows).rows

const RANK = (w: Worker) => (w.state === 'ask' ? 0 : !w.end ? 1 : w.state === 'failed' ? 2 : 3)

export const clock = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000))
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}
const kilo = (n: number) => (n >= 1000 ? `${(n / 1000).toFixed(n >= 10_000 ? 0 : 1)}k` : String(n))
const shorten = (s: string, n: number) => {
  const one = s.replace(/\s+/g, ' ').trim()
  return [...one].length <= n ? one : '…' + [...one].slice(-(n - 1)).join('')
}
function wrap(s: string, width: number, lines: number): string[] {
  const out: string[] = []
  let cur = ''
  for (const word of s.replace(/^[#>*\s\d.]*(goal:)?\s*/i, '').split(/\s+/)) {
    if (!word) continue
    const next = cur ? `${cur} ${word}` : word
    if ([...next].length <= width) { cur = next; continue }
    if (cur) out.push(cur)
    cur = [...word].slice(0, width).join('')
    if (out.length === lines) break
  }
  if (cur && out.length < lines) out.push(cur)
  if (out.length === lines && [...out.join(' ')].length < [...s].length - 2) {
    const last = [...(out[lines - 1] ?? '')]
    out[lines - 1] = last.slice(0, Math.max(0, width - 1)).join('') + '…'
  }
  return out.slice(0, lines)
}

// MSYS path (/c/Users/x) -> C:/Users/x so $.fs can read it; other paths pass through.
export const msysToWin = (p: string) => p.replace(/^\/([a-zA-Z])(?=\/|$)/, (_, d: string) => `${d.toUpperCase()}:`)

// A path reads by its file name: the folders dim, the name bright. A command shows whole.
function target(g: Grid, x: number, y: number, arg: string, max: number, bright: number, faint: number) {
  if (max < 2 || !arg) return 0
  const s = shorten(arg, max)
  const cut = /\s/.test(arg.trim()) ? 0 : Math.max(s.lastIndexOf('/'), s.lastIndexOf('\\')) + 1
  const n = g.text(x, y, s.slice(0, cut), faint, max)
  return n + g.text(x + n, y, s.slice(cut), bright, max - n)
}

const BARS = '▂▃▅▆▇'
// Tools per BUCKET_MS bucket, newest on the right, each bar in the colour of its last tool's kind:
// the worker's rhythm at a glance, and a flat line when it has gone quiet.
function activity(g: Grid, w: Worker, x: number, y: number, n: number, now: number, fade: number) {
  if (n <= 0) return
  const anchor = Math.ceil((w.end ?? now) / BUCKET_MS) * BUCKET_MS
  const from = anchor - n * BUCKET_MS
  const count = new Array<number>(n).fill(0), kind = new Array<Kind | undefined>(n)
  w.times.forEach((t, i) => {
    const b = Math.floor((t - from) / BUCKET_MS)
    if (b < 0 || b >= n) return
    count[b] = (count[b] ?? 0) + 1
    kind[b] = w.trail[i]
  })
  for (let i = 0; i < n; i++) {
    const t0 = from + i * BUCKET_MS
    if (t0 + BUCKET_MS < w.start) continue
    const k = count[i] ?? 0, kd = kind[i]
    if (!k || !kd) g.put(x + i, y, '▁', mix(FAINT, BASE, 0.35))
    else g.put(x + i, y, BARS[Math.min(BARS.length - 1, k - 1)] ?? '▇', mix(KIND_COLOR[kd], BASE, fade))
  }
}

type Place = (look: Look, x: number, y: number, alt: string) => void

function card(g: Grid, w: Worker, x0: number, y0: number, W: number, now: number, place: Place) {
  const f = Math.floor(now / FRAME_MS)
  const opus = /opus/i.test(w.model)
  const theme = opus ? OPUS_THEME : THEME[w.role]
  const sc = STATE_COLOR[w.state]
  const over = w.end !== undefined && w.state !== 'ask'
  // A finished card steps back: its words sink toward the panel.
  const fade = over ? 0.4 : 0
  const ink = (c: number) => mix(c, BASE, fade)
  const accent =
    w.state === 'ask' ? mix(dim(sc, 0.5), sc, pulse(now, 1600))
    : w.state === 'blocked' || w.state === 'error' ? mix(dim(sc, 0.45), sc, pulse(now, 700))
    : over ? dim(sc, 0.7)
    : mix(dim(theme, 0.75), theme, pulse(now + hash(w.key) * 37, 2400))

  // A rounded frame on the terminal's background; its left side in the state's colour.
  const R = x0 + W - 1, B = y0 + CARD_H - 1
  const edge = over ? mix(EDGE, BASE, 0.4) : EDGE
  for (let x = x0 + 1; x < R; x++) g.put(x, y0, '─', edge)
  for (let y = y0 + 1; y < B; y++) { g.put(x0, y, '┃', accent); g.put(R, y, '│', edge) }
  g.put(x0, y0, '┎', accent); g.put(R, y0, '╮', edge)
  g.put(x0, B, '┖', accent); g.put(R, B, '╯', edge)

  // The bottom edge is a bar: the run's time budget while it works (amber, then red, as it runs
  // out), the countdown until a finished card leaves, full and breathing while a question waits.
  const inner = W - 2
  let frac = 0, bar = theme
  if (w.state === 'ask') { frac = 1; bar = mix(dim(sc, 0.55), sc, pulse(now, 1600)) }
  else if (over) { frac = 1 - (now - (w.end ?? now)) / KEEP_MS; bar = dim(sc, 0.6) }
  else {
    frac = (now - w.runStart) / Math.max(1, w.tmo * 1000)
    bar = frac > 0.9 ? 0xff5c5c : frac > 0.75 ? 0xffb347 : dim(theme, 0.8)
  }
  const fill = Math.round(Math.max(0, Math.min(1, frac)) * inner)
  for (let i = 0; i < inner; i++) g.put(x0 + 1 + i, B, i < fill ? '━' : '─', i < fill ? bar : edge)

  place(lookAt(w.role, w.model, w.state, now, w.stateAt, hash(w.key)), x0 + 2, y0 + 1, `${w.name} ${LABEL[w.state]}`)

  const X = x0 + MW + 3, TW = R - X - 1
  if (TW < 8) return
  const row = (i: number) => y0 + 1 + i

  // 1: who — name, model chip, effort pips; the clock on the right
  const elapsed = clock((w.end ?? now) - w.start)
  const clockX = R - 1 - elapsed.length
  g.text(clockX, row(0), elapsed, over ? ink(DIM) : TEXT)
  let x = X + g.text(X, row(0), w.name, ink(theme), clockX - X - 1)
  const room = () => clockX - x - 2
  if (room() > 4) x += 1 + g.pill(x + 1, row(0), w.model.toUpperCase(), ink(theme), mix(BASE, theme, over ? 0.12 : 0.22), room())
  const eff = EFFORT[w.effort]
  if (eff && room() > 4) {
    x += 1
    for (let i = 0; i < 3; i++) g.put(x + i, row(0), i < eff[0] ? '●' : '○', i < eff[0] ? ink(eff[1]) : mix(FAINT, BASE, 0.3))
    x += 3
  }
  if (w.resumed && room() > 2) g.put(x + 1, row(0), '↻', ink(0xffe082))

  // 2: what it is doing now, and on what
  const icon =
    w.state === 'done' ? '✓' : w.state === 'failed' ? '✗' : w.state === 'ask' ? '?'
    : w.state === 'blocked' || w.state === 'error' ? '!' : SPIN[f % SPIN.length] ?? ' '
  g.put(X, row(1), icon, ink(sc))
  let lx = X + 2 + g.text(X + 2, row(1), LABEL[w.state], ink(sc), TW - 2)
  const quiet = !w.end ? now - w.lastAt : 0
  if (quiet > QUIET_MS && w.state === 'think') {
    lx += g.text(lx, row(1), ` · ${clock(quiet)} sessiz`, mix(0xffb347, BASE, 0.25 * pulse(now, 2000)), X + TW - lx)
  } else if (w.arg && w.state !== 'ask' && X + TW - lx > 6) {
    lx += 1 + g.text(lx + 1, row(1), '·', FAINT)
    target(g, lx + 1, row(1), w.arg, X + TW - lx - 1, ink(0xc9d6e6), ink(0x6d7891))
  }

  // 3–4: the question while one waits; else the task and the activity strip
  if (w.state === 'ask' && w.question) {
    wrap(w.question, TW, 2).forEach((line, i) => g.text(X, row(2 + i), line, 0xffe8a3))
    return
  }
  wrap(w.task, TW, 1).forEach(line => g.text(X, row(2), line, ink(DIM)))
  const stats = over ? `${w.turns} turns · ${kilo(w.out)} tok`
    : `${w.trail.length} tools${w.blocked ? ` · ${w.blocked} blocked` : ''}`
  const sw = [...stats].length
  const strip = TW - sw - 2
  if (strip >= 6) activity(g, w, X, row(3), strip, now, fade)
  g.text(X + TW - sw, row(3), stats, w.blocked && !w.end ? 0xff9e9e : ink(DIM))
}

function line(g: Grid, w: Worker, x0: number, y: number, W: number, now: number) {
  const f = Math.floor(now / FRAME_MS)
  const sc = STATE_COLOR[w.state]
  const icon =
    w.state === 'done' ? '✓' : w.state === 'failed' ? '✗' : w.state === 'ask' ? '?'
    : w.state === 'blocked' || w.state === 'error' ? '!' : SPIN[f % SPIN.length] ?? ' '
  const R = x0 + W - 1
  const elapsed = clock((w.end ?? now) - w.start)
  g.text(R - elapsed.length, y, elapsed, w.end ? DIM : TEXT)
  const end = R - elapsed.length - 1
  let x = x0 + 1
  g.put(x, y, icon, sc); x += 2
  x += g.text(x, y, w.name, /opus/i.test(w.model) ? OPUS_THEME : THEME[w.role], end - x)
  x += 1 + g.text(x + 1, y, LABEL[w.state], sc, end - x - 1)
  const rest = w.state === 'ask' ? (w.question ?? '') : w.arg || w.task
  if (end - x > 4) g.text(x + 1, y, shorten(rest, end - x - 2), DIM)
}

function header(g: Grid, ws: Worker[], now: number) {
  // the crew's colours drift through the title's diamond and the rule's travelling glow
  const hues = [0x4fd1c5, 0x64b5f6, 0xb39ddb, 0xffb347, 0xffd166]
  const t = (now / 1600) % hues.length
  const hue = mix(hues[Math.floor(t)] ?? 0x4fd1c5, hues[(Math.floor(t) + 1) % hues.length] ?? 0x4fd1c5, t % 1)
  g.put(1, 0, '◆', hue)
  let x = 3 + g.text(3, 0, 'CREW', TEXT)
  const active = ws.filter(w => !w.end).length
  const asking = ws.filter(w => w.state === 'ask').length
  const done = ws.filter(w => w.state === 'done').length
  const failed = ws.filter(w => w.state === 'failed').length
  const chips: [string, number, boolean][] = [
    active ? [`● ${active} working`, 0x81c784, true] : ['○ idle', DIM, true], [`? ${asking} asking`, 0xffd166, asking > 0],
    [`✓ ${done}`, 0x7bd88f, done > 0], [`✗ ${failed}`, 0xff5c5c, failed > 0],
  ]
  // the activity of the whole crew over the last two minutes, and its rate
  const SPAN = 12, B = 10_000
  const from = Math.ceil(now / B) * B - SPAN * B
  const per = new Array<number>(SPAN).fill(0)
  let minute = 0
  for (const w of ws) for (const tt of w.times) {
    const b = Math.floor((tt - from) / B)
    if (b >= 0 && b < SPAN) per[b] = (per[b] ?? 0) + 1
    if (now - tt < 60_000) minute++
  }
  const rate = `${minute}/dk`
  const sparkW = SPAN + 1 + rate.length
  const right = g.w - 1 - sparkW
  for (const [s, c, on] of chips) {
    if (!on) continue
    const wdt = [...s].length + 2
    if (x + 1 + wdt >= right - 1) break
    x += 1 + g.pill(x + 1, 0, s, c === 0xffd166 ? mix(c, 0xffffff, 0.2 * pulse(now, 1600)) : c, mix(BASE, c, 0.18))
  }
  if (right > x + 1 && ws.length) {
    const top = Math.max(1, ...per)
    per.forEach((k, i) => g.put(right + i, 0, k ? (BARS[Math.min(BARS.length - 1, Math.ceil((k / top) * BARS.length) - 1)] ?? '▇') : '▁',
      k ? mix(0x4fd1c5, 0xb39ddb, i / SPAN) : FAINT))
    g.text(right + SPAN + 1, 0, rate, minute ? DIM : FAINT)
  }
  const head = ((now / 18) % (g.w + 30)) - 15
  for (let i = 0; i < g.w; i++) {
    const d = Math.abs(i - head)
    g.put(i, 1, '─', d < 10 ? mix(0x2c2f3a, hue, (1 - d / 10) ** 2) : 0x2c2f3a)
  }
}

// `images`: leave each sprite's cells blank and list it in `spots`, for an Image laid over them.
// `hits`: where each card's "details" button goes (its bottom edge, right side), for a Button laid over it.
export const DETAILS = 'details ›'
export type Hit = { key: string; x: number; y: number }
export function drawScene(
  ws: Worker[], cols: number, now: number, maxRows?: number, images = false,
): { rows: number; words: Uint32Array; spots: Spot[]; hits: Hit[] } {
  const fit = layout(ws.length, cols, maxRows)
  const rows = fit.rows
  const g = new Grid(cols, rows)
  const spots: Spot[] = []
  const hits: Hit[] = []
  const place: Place = (look, x, y, alt) => {
    if (images) spots.push({ key: `s${spots.length}`, x, y, look, alt })
    else g.pixels(smallSprite(look), x, y)
  }
  header(g, ws, now)
  if (ws.length === 0) {
    const half = Math.floor(cols / 2)
    for (const [i, role] of (['scout', 'coder'] as Role[]).entries()) {
      const cx = Math.max(0, (i ? half : 0) + Math.floor((half - MW) / 2))
      place(lookAt(role, role === 'scout' ? 'haiku' : 'sonnet', 'sleep', now, 0, i * 5), cx, HEADER_H + 1, `${role} uyuyor`)
      const label = role === 'scout' ? 'scout · haiku' : 'coder · sonnet'
      g.text(Math.max(0, (i ? half : 0) + Math.floor((half - label.length) / 2)), HEADER_H + 2 + MH, label, dim(THEME[role], 0.8))
    }
    const msg = 'no workers · /orchestrate wakes them'
    g.text(Math.max(0, Math.floor((cols - [...msg].length) / 2)), HEADER_H + MH + 3, msg, FAINT)
    return { rows, words: g.words(), spots, hits }
  }
  const per = perRow(cols)
  const W = Math.floor(cols / per)
  const cw = per > 1 ? W - 1 : W
  // Overflowing: questions and live workers keep the cards, finished ones drop to lines first.
  const list = fit.cards < ws.length ? [...ws].sort((a, b) => RANK(a) - RANK(b)) : ws
  list.slice(0, fit.cards).forEach((w, i) => {
    const x0 = (i % per) * W, y0 = HEADER_H + Math.floor(i / per) * CARD_H
    card(g, w, x0, y0, cw, now, place)
    hits.push({ key: w.key, x: Math.max(x0 + 2, x0 + cw - DETAILS.length - 3), y: y0 + CARD_H - 1 })
  })
  const top = HEADER_H + Math.ceil(fit.cards / per) * CARD_H
  list.slice(fit.cards, fit.cards + fit.lines * per)
    .forEach((w, i) => line(g, w, (i % per) * W, top + Math.floor(i / per), W, now))
  if (fit.more > 0) {
    const msg = `+${fit.more} more · enlarge the pane`
    g.text(Math.max(0, Math.floor((cols - [...msg].length) / 2)), rows - 1, msg, DIM)
  }
  return { rows, words: g.words(), spots, hits }
}

// ---------- svg (surfaces with no Raster: desktop, editor, mobile) ----------

// One cell is CW x CH; each half-block pixel (CW x CH/2) comes out square. Every cell splits into
// 2x2 quarters so ▀▄█▌▐ map to rects, merged into runs and one path per colour; other glyphs are text.
const CW = 6, CH = 12
const hex = (c: number) => `#${(c & 0xffffff).toString(16).padStart(6, '0')}`
const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
const QUARTERS: Record<number, number> = { 0x2580: 0b1100, 0x2584: 0b0011, 0x2588: 0b1111, 0x258c: 0b1010, 0x2590: 0b0101 }

// `sprites`: PNG frames laid over the blank cells drawScene(images = true) left, as data URIs.
export type SvgSprite = { x: number; y: number; base64: string }
export function sceneSvg(words: Uint32Array, cols: number, rows: number, sprites: SvgSprite[] = [], scale = 1.5): string {
  const q = new Int32Array(cols * 2 * rows * 2).fill(-1)
  const texts: string[] = []
  for (let y = 0; y < rows; y++) {
    // Runs end at spaces: a surface may collapse them, and textLength would then stretch the rest.
    let run = '', runX = 0, runFg = -1
    const flush = () => {
      if (run) {
        const n = [...run].length
        texts.push(`<text x="${runX * CW}" y="${y * CH + 9.5}" fill="${hex(runFg)}" textLength="${n * CW}" lengthAdjust="spacingAndGlyphs">${esc(run)}</text>`)
      }
      run = ''; runFg = -1
    }
    for (let x = 0; x < cols; x++) {
      const i = (y * cols + x) * 3
      const g = words[i] ?? 0x20, fg = words[i + 1] ?? DEF, bg = words[i + 2] ?? DEF
      const fill = (mask: number, c: number) => {
        if (c === DEF) return
        for (let k = 0; k < 4; k++) if (mask & (8 >> k)) q[(y * 2 + (k >> 1)) * cols * 2 + x * 2 + (k & 1)] = c & 0xffffff
      }
      fill(0b1111, bg)
      const mask = QUARTERS[g]
      if (mask !== undefined) { fill(mask, fg === DEF ? TEXT : fg); flush(); continue }
      const c = fg === DEF ? TEXT : fg & 0xffffff
      if (g === 0x20) { flush(); continue }
      if (run && c !== runFg) flush()
      if (!run) { runX = x; runFg = c }
      run += String.fromCodePoint(g)
    }
    flush()
  }
  const paths = new Map<number, string>()
  const W = cols * 2
  for (let j = 0; j < rows * 2; j++) {
    for (let i = 0; i < W;) {
      const c = q[j * W + i] ?? -1
      let k = i + 1
      while (k < W && q[j * W + k] === c) k++
      if (c >= 0) {
        const w = ((k - i) * CW) / 2
        paths.set(c, `${paths.get(c) ?? ''}M${(i * CW) / 2} ${(j * CH) / 2}h${w}v${CH / 2}h-${w}z`)
      }
      i = k
    }
  }
  const vw = cols * CW, vh = rows * CH
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${vw} ${vh}" width="${vw * scale}" height="${vh * scale}">` +
    `<rect width="${vw}" height="${vh}" rx="6" fill="${hex(0x1b1c22)}"/>` +
    [...paths].map(([c, d]) => `<path fill="${hex(c)}" d="${d}"/>`).join('') +
    sprites.map(s => `<image x="${s.x * CW}" y="${s.y * CH}" width="${MW * CW}" height="${MH * CH}" style="image-rendering:pixelated" href="data:image/png;base64,${s.base64}"/>`).join('') +
    `<g font-family="ui-monospace,Menlo,Consolas,monospace" font-size="10">${texts.join('')}</g></svg>`
}

